window.CODIGO_JAVA["compras-proveedores-ms"] = {"src/main/java/com/mx/josesaid/develop/compras/ComprasApplication.java": "package com.mx.josesaid.develop.compras;\n\nimport org.springframework.boot.SpringApplication;\nimport org.springframework.boot.autoconfigure.SpringBootApplication;\nimport org.springframework.boot.context.properties.ConfigurationPropertiesScan;\nimport org.springframework.scheduling.annotation.EnableScheduling;\n\n/** Punto de entrada de compras-proveedores-ms. */\n@SpringBootApplication\n@EnableScheduling\n@ConfigurationPropertiesScan\npublic class ComprasApplication {\n\n    /** Arranca la aplicación Spring Boot. */\n    public static void main(String[] args) {\n        SpringApplication.run(ComprasApplication.class, args);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/api/ComprasControlador.java": "package com.mx.josesaid.develop.compras.api;\n\nimport com.mx.josesaid.develop.compras.application.ComprasService;\nimport com.mx.josesaid.develop.compras.application.LineaRecibida;\nimport com.mx.josesaid.develop.compras.domain.EstatusOrdenCompra;\nimport com.mx.josesaid.develop.compras.domain.EstatusProveedor;\nimport com.mx.josesaid.develop.compras.domain.LineaOrden;\nimport com.mx.josesaid.develop.compras.domain.OrdenCompra;\nimport com.mx.josesaid.develop.compras.domain.Proveedor;\nimport jakarta.validation.Valid;\nimport jakarta.validation.constraints.Digits;\nimport jakarta.validation.constraints.DecimalMin;\nimport jakarta.validation.constraints.Email;\nimport jakarta.validation.constraints.NotBlank;\nimport jakarta.validation.constraints.NotEmpty;\nimport jakarta.validation.constraints.NotNull;\nimport jakarta.validation.constraints.Positive;\nimport jakarta.validation.constraints.Size;\nimport java.math.BigDecimal;\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.security.access.prepost.PreAuthorize;\nimport org.springframework.security.core.Authentication;\nimport org.springframework.security.core.annotation.AuthenticationPrincipal;\nimport org.springframework.security.oauth2.jwt.Jwt;\nimport org.springframework.web.bind.annotation.GetMapping;\nimport org.springframework.web.bind.annotation.PathVariable;\nimport org.springframework.web.bind.annotation.PostMapping;\nimport org.springframework.web.bind.annotation.RequestBody;\nimport org.springframework.web.bind.annotation.RequestParam;\nimport org.springframework.web.bind.annotation.RequestMapping;\nimport org.springframework.web.bind.annotation.ResponseStatus;\nimport org.springframework.web.bind.annotation.RestController;\nimport com.mx.josesaid.develop.compras.infrastructure.idempotencia.Idempotencia;\nimport org.springframework.web.bind.annotation.RequestHeader;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.validation.annotation.Validated;\n\n/**\n * Proveedores y órdenes de compra. Los datos fiscales se enmascaran en las respuestas.\n * GET /ordenes-compra/{id} se añade a la especificación para consultar el estado de cada compra.\n */\n@Validated\n@RestController\n@RequestMapping(\"/v1\")\npublic class ComprasControlador {\n\n    private final ComprasService servicio;\n    private final Idempotencia idempotencia;\n\n    /** Recibe el servicio de compras y el control de idempotencia. */\n    public ComprasControlador(ComprasService servicio, Idempotencia idempotencia) {\n        this.servicio = servicio;\n        this.idempotencia = idempotencia;\n    }\n\n    /** Da de alta un proveedor. */\n    @PostMapping(\"/proveedores\")\n    @ResponseStatus(HttpStatus.CREATED)\n    @PreAuthorize(\"hasRole('COMPRAS')\")\n    public ProveedorRespuesta crearProveedor(@Valid @RequestBody CrearProveedorSolicitud s) {\n        return ProveedorRespuesta.de(servicio.crearProveedor(s.razonSocial(), s.rfc(), s.correo()));\n    }\n\n    /** Busca proveedores por texto en la razón social. */\n    @GetMapping(\"/proveedores\")\n    @PreAuthorize(\"hasAnyRole('COMPRAS','FINANZAS')\")\n    public List<ProveedorRespuesta> buscarProveedores(@RequestParam @Size(max = 250) String razonSocial) {\n        return servicio.buscarProveedores(razonSocial).stream().map(ProveedorRespuesta::de).toList();\n    }\n\n    /** Devuelve un proveedor por id. */\n    @GetMapping(\"/proveedores/{id}\")\n    @PreAuthorize(\"hasAnyRole('COMPRAS','FINANZAS')\")\n    public ProveedorRespuesta obtenerProveedor(@PathVariable UUID id) {\n        return ProveedorRespuesta.de(servicio.obtenerProveedor(id));\n    }\n\n    /** Crea una orden de compra en borrador. Acepta Idempotency-Key. */\n    @PostMapping(\"/ordenes-compra\")\n    @PreAuthorize(\"hasRole('COMPRAS')\")\n    public ResponseEntity<?> crearOrden(@RequestHeader(value = Idempotencia.CABECERA, required = false) String clave,\n                                        @Valid @RequestBody CrearOrdenSolicitud s,\n                                        @AuthenticationPrincipal Jwt jwt) {\n        return idempotencia.ejecutar(clave, \"POST /v1/ordenes-compra\", s, HttpStatus.CREATED, () -> {\n            List<LineaOrden> lineas = s.lineas().stream()\n                    .map(l -> LineaOrden.nueva(l.articuloSku(), l.cantidad(), l.precioUnitario()))\n                    .toList();\n            return OrdenRespuesta.de(servicio.crearOrden(s.proveedorId(), s.moneda(), lineas, jwt.getSubject()));\n        });\n    }\n\n    /** Lista las órdenes recientes, opcionalmente filtradas por estatus. */\n    @GetMapping(\"/ordenes-compra\")\n    @PreAuthorize(\"hasAnyRole('COMPRAS','ALMACEN','DIRECCION')\")\n    public List<ResumenOrdenRespuesta> listarOrdenes(\n            @RequestParam(required = false) com.mx.josesaid.develop.compras.domain.EstatusOrdenCompra estatus) {\n        return servicio.listarOrdenesRecientes(estatus).stream()\n                .map(r -> new ResumenOrdenRespuesta(r.id(), r.estatus(), r.razonSocialProveedor(), r.creadaUtc()))\n                .toList();\n    }\n\n    /** Devuelve una orden de compra con sus líneas. */\n    @GetMapping(\"/ordenes-compra/{id}\")\n    @PreAuthorize(\"hasAnyRole('COMPRAS','ALMACEN','DIRECCION')\")\n    public OrdenRespuesta obtenerOrden(@PathVariable UUID id) {\n        return OrdenRespuesta.de(servicio.obtenerOrden(id));\n    }\n\n    /** Aprueba la orden si el usuario puede hacerlo. Las reglas de aprobación están en la orden. */\n    @PostMapping(\"/ordenes-compra/{id}/aprobacion\")\n    @PreAuthorize(\"hasAnyRole('COMPRAS','DIRECCION')\")\n    public OrdenRespuesta aprobarOrden(@PathVariable UUID id, @AuthenticationPrincipal Jwt jwt,\n                                       Authentication autenticacion) {\n        boolean esDireccion = autenticacion.getAuthorities().stream()\n                .anyMatch(a -> \"ROLE_DIRECCION\".equals(a.getAuthority()));\n        return OrdenRespuesta.de(servicio.aprobarOrden(id, jwt.getSubject(), esDireccion));\n    }\n\n    /** Registra la recepción de mercancía. No puede superar lo ordenado. */\n    @PostMapping(\"/ordenes-compra/{id}/recepciones\")\n    @ResponseStatus(HttpStatus.CREATED)\n    @PreAuthorize(\"hasRole('ALMACEN')\")\n    public OrdenRespuesta registrarRecepcion(@PathVariable UUID id, @Valid @RequestBody RecepcionSolicitud s) {\n        return OrdenRespuesta.de(servicio.registrarRecepcion(id,\n                s.lineas().stream().map(l -> new LineaRecibida(l.articuloSku(), l.cantidad())).toList()));\n    }\n\n    /** Cancela una orden en borrador o aprobada. Requiere motivo. */\n    @PostMapping(\"/ordenes-compra/{id}/cancelacion\")\n    @PreAuthorize(\"hasRole('COMPRAS')\")\n    public OrdenRespuesta cancelarOrden(@PathVariable UUID id, @Valid @RequestBody CancelarSolicitud s) {\n        return OrdenRespuesta.de(servicio.cancelarOrden(id, s.motivo()));\n    }\n\n    /**\n     * Datos para dar de alta un proveedor.\n     *\n     * @param razonSocial razón social, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     */\n    public record CrearProveedorSolicitud(\n            @NotBlank @Size(max = 200) String razonSocial,\n            @NotBlank @Size(max = 13) String rfc,\n            @NotBlank @Email @Size(max = 254) String correo) {\n    }\n\n    /**\n     * Línea de una orden: SKU, cantidad y precio unitario.\n     *\n     * @param articuloSku articulo sku, de tipo {@code String}.\n     * @param cantidad cantidad solicitada o registrada, de tipo {@code BigDecimal}.\n     * @param precioUnitario precio unitario, de tipo {@code BigDecimal}.\n     */\n    public record LineaSolicitud(\n            @NotBlank @Size(max = 40) String articuloSku,\n            @NotNull @Positive @Digits(integer = 9, fraction = 3) BigDecimal cantidad,\n            @NotNull @DecimalMin(\"0\") @Digits(integer = 10, fraction = 2) BigDecimal precioUnitario) {\n    }\n\n    /**\n     * Datos para crear una orden: proveedor, moneda y líneas.\n     *\n     * @param proveedorId identificador del proveedor, de tipo {@code UUID}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param lineas líneas o renglones del documento, de tipo {@code List<LineaSolicitud>}.\n     */\n    public record CrearOrdenSolicitud(\n            @NotNull UUID proveedorId,\n            @NotBlank @Size(max = 3) String moneda,\n            @NotEmpty @Size(max = 100) List<@Valid LineaSolicitud> lineas) {\n    }\n\n    /**\n     * Línea recibida: SKU y cantidad.\n     *\n     * @param articuloSku articulo sku, de tipo {@code String}.\n     * @param cantidad cantidad solicitada o registrada, de tipo {@code BigDecimal}.\n     */\n    public record LineaRecepcionSolicitud(@NotBlank String articuloSku, @NotNull @Positive @Digits(integer = 9, fraction = 3) BigDecimal cantidad) {\n    }\n\n    /**\n     * Lista de líneas recibidas en una recepción.\n     *\n     * @param lineas líneas o renglones del documento, de tipo {@code List<LineaRecepcionSolicitud>}.\n     */\n    public record RecepcionSolicitud(@NotEmpty @Size(max = 100) List<@Valid LineaRecepcionSolicitud> lineas) {\n    }\n\n    /**\n     * Motivo de la cancelación, de hasta 200 caracteres.\n     *\n     * @param motivo motivo del registro o de la acción, de tipo {@code String}.\n     */\n    public record CancelarSolicitud(@NotBlank @Size(max = 200) String motivo) {\n    }\n\n    /**\n     * Respuesta de un proveedor.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param razonSocial razón social, de tipo {@code String}.\n     * @param rfc RFC fiscal de la persona o empresa, de tipo {@code String}.\n     * @param correo correo electrónico de contacto, de tipo {@code String}.\n     * @param estatus estado actual del registro, de tipo {@code EstatusProveedor}.\n     */\n    public record ProveedorRespuesta(UUID id, String razonSocial, String rfc, String correo, EstatusProveedor estatus) {\n        /** Convierte un proveedor en su respuesta. */\n        static ProveedorRespuesta de(Proveedor p) {\n            return new ProveedorRespuesta(p.getId(), p.getRazonSocial(), enmascararRfc(p.getRfc()),\n                    enmascararCorreo(p.getCorreo()), p.getEstatus());\n        }\n\n        /** Muestra las primeras 3 y últimas 2 posiciones del RFC. */\n        static String enmascararRfc(String rfc) {\n            if (rfc == null || rfc.length() < 6) {\n                return \"***\";\n            }\n            return rfc.substring(0, 3) + \"*\".repeat(rfc.length() - 5) + rfc.substring(rfc.length() - 2);\n        }\n\n        /** Muestra la primera letra del correo y el dominio. */\n        static String enmascararCorreo(String correo) {\n            int arroba = correo.indexOf('@');\n            return arroba <= 0 ? \"***\" : correo.charAt(0) + \"***\" + correo.substring(arroba);\n        }\n    }\n\n    /**\n     * Respuesta de una línea de orden, con las cantidades ordenada y recibida.\n     *\n     * @param articuloSku articulo sku, de tipo {@code String}.\n     * @param cantidadOrdenada cantidad ordenada, de tipo {@code BigDecimal}.\n     * @param cantidadRecibida cantidad recibida, de tipo {@code BigDecimal}.\n     * @param precioUnitario precio unitario, de tipo {@code BigDecimal}.\n     * @param subtotal subtotal antes de impuestos, de tipo {@code BigDecimal}.\n     */\n    public record LineaRespuesta(String articuloSku, BigDecimal cantidadOrdenada, BigDecimal cantidadRecibida,\n                                 BigDecimal precioUnitario, BigDecimal subtotal) {\n    }\n\n    /**\n     * Resumen de una orden para los listados.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param estatus estado actual del registro, de tipo {@code EstatusOrdenCompra}.\n     * @param razonSocialProveedor razon social proveedor, de tipo {@code String}.\n     * @param creadaUtc creada utc, de tipo {@code java.time.Instant}.\n     */\n    public record ResumenOrdenRespuesta(UUID id, EstatusOrdenCompra estatus, String razonSocialProveedor,\n                                        java.time.Instant creadaUtc) {\n    }\n\n    /**\n     * Respuesta de una orden de compra.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param proveedorId identificador del proveedor, de tipo {@code UUID}.\n     * @param estatus estado actual del registro, de tipo {@code EstatusOrdenCompra}.\n     * @param moneda código de moneda (por ejemplo, MXN), de tipo {@code String}.\n     * @param total importe total, de tipo {@code BigDecimal}.\n     * @param motivoCancelacion motivo cancelacion, de tipo {@code String}.\n     * @param lineas líneas o renglones del documento, de tipo {@code List<LineaRespuesta>}.\n     */\n    public record OrdenRespuesta(UUID id, UUID proveedorId, EstatusOrdenCompra estatus, String moneda,\n                                 BigDecimal total, String motivoCancelacion, List<LineaRespuesta> lineas) {\n        /** Convierte una orden en su respuesta. */\n        static OrdenRespuesta de(OrdenCompra o) {\n            return new OrdenRespuesta(o.getId(), o.getProveedorId(), o.getEstatus(), o.getMoneda(), o.total(),\n                    o.getMotivoCancelacion(),\n                    o.getLineas().stream()\n                            .map(l -> new LineaRespuesta(l.getArticuloSku(), l.getCantidadOrdenada(),\n                                    l.getCantidadRecibida(), l.getPrecioUnitario(), l.subtotal()))\n                            .toList());\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/api/ManejadorErrores.java": "package com.mx.josesaid.develop.compras.api;\n\nimport com.mx.josesaid.develop.compras.domain.AprobacionNoPermitidaException;\nimport com.mx.josesaid.develop.compras.domain.ConflictoException;\nimport com.mx.josesaid.develop.compras.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.compras.domain.ReglaDeNegocioException;\nimport com.mx.josesaid.develop.compras.domain.SolicitudInvalidaException;\nimport java.net.URI;\nimport java.util.stream.Collectors;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.ProblemDetail;\nimport org.springframework.orm.ObjectOptimisticLockingFailureException;\nimport org.springframework.web.bind.MethodArgumentNotValidException;\nimport org.springframework.web.bind.annotation.ExceptionHandler;\nimport org.springframework.web.bind.annotation.RestControllerAdvice;\n\n/** Errores RFC 9457 con type {@code urn:josesaid:compras-proveedores:error:<slug>}. */\n@RestControllerAdvice\npublic class ManejadorErrores {\n\n    private static final String PREFIJO = \"urn:josesaid:compras-proveedores:error:\";\n\n    /** Convierte un recurso inexistente en un problema HTTP. */\n    @ExceptionHandler(RecursoNoEncontradoException.class)\n    ProblemDetail noEncontrado(RecursoNoEncontradoException ex) {\n        return problema(HttpStatus.NOT_FOUND, \"no-encontrado\", ex.getMessage());\n    }\n\n    /** Convierte un intento de aprobación no permitido en un problema HTTP. */\n    @ExceptionHandler(AprobacionNoPermitidaException.class)\n    ProblemDetail aprobacionNoPermitida(AprobacionNoPermitidaException ex) {\n        return problema(HttpStatus.FORBIDDEN, \"aprobacion-no-permitida\", ex.getMessage());\n    }\n\n    /** Convierte un conflicto de estado en un problema HTTP. */\n    @ExceptionHandler(ConflictoException.class)\n    ProblemDetail conflicto(ConflictoException ex) {\n        return problema(HttpStatus.CONFLICT, \"conflicto\", ex.getMessage());\n    }\n\n    /** Convierte un conflicto de concurrencia en un problema HTTP. El cliente debe reintentar. */\n    @ExceptionHandler(ObjectOptimisticLockingFailureException.class)\n    ProblemDetail concurrencia(ObjectOptimisticLockingFailureException ex) {\n        return problema(HttpStatus.CONFLICT, \"conflicto-concurrencia\",\n                \"El registro cambió mientras se procesaba. Vuelva a intentarlo.\");\n    }\n\n    /** Convierte una regla de negocio incumplida en un problema HTTP. */\n    @ExceptionHandler(ReglaDeNegocioException.class)\n    ProblemDetail reglaDeNegocio(ReglaDeNegocioException ex) {\n        return problema(HttpStatus.UNPROCESSABLE_ENTITY, \"regla-de-negocio\", ex.getMessage());\n    }\n\n    /** Convierte una solicitud inválida en un problema HTTP. */\n    @ExceptionHandler(SolicitudInvalidaException.class)\n    ProblemDetail solicitudInvalida(SolicitudInvalidaException ex) {\n        return problema(HttpStatus.BAD_REQUEST, \"datos-invalidos\", ex.getMessage());\n    }\n\n    /** Convierte errores de validación en un problema HTTP con el detalle de cada campo. */\n    @ExceptionHandler(MethodArgumentNotValidException.class)\n    ProblemDetail validacion(MethodArgumentNotValidException ex) {\n        String detalle = ex.getBindingResult().getFieldErrors().stream()\n                .map(e -> e.getField() + \": \" + e.getDefaultMessage())\n                .collect(Collectors.joining(\"; \"));\n        return problema(HttpStatus.BAD_REQUEST, \"datos-invalidos\", detalle);\n    }\n\n    /** Construye la respuesta de error con su estatus, código y detalle. */\n    private static ProblemDetail problema(HttpStatus estatus, String slug, String detalle) {\n        ProblemDetail pd = ProblemDetail.forStatusAndDetail(estatus, detalle);\n        pd.setType(URI.create(PREFIJO + slug));\n        pd.setTitle(estatus.getReasonPhrase());\n        return pd;\n    }\n\n    /** Convierte parámetros inválidos en un problema HTTP. */\n    @org.springframework.web.bind.annotation.ExceptionHandler(jakarta.validation.ConstraintViolationException.class)\n    org.springframework.http.ProblemDetail parametrosInvalidos(jakarta.validation.ConstraintViolationException e) {\n        return org.springframework.http.ProblemDetail.forStatusAndDetail(\n                org.springframework.http.HttpStatus.BAD_REQUEST, \"Revise los parámetros indicados\");\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/application/ComprasService.java": "package com.mx.josesaid.develop.compras.application;\n\nimport com.mx.josesaid.develop.compras.domain.ConflictoException;\nimport com.mx.josesaid.develop.compras.domain.EstatusOrdenCompra;\nimport com.mx.josesaid.develop.compras.domain.LineaOrden;\nimport com.mx.josesaid.develop.compras.domain.OrdenCompra;\nimport com.mx.josesaid.develop.compras.domain.OrdenCompraRepositorio;\nimport com.mx.josesaid.develop.compras.domain.Proveedor;\nimport com.mx.josesaid.develop.compras.domain.ProveedorRepositorio;\nimport com.mx.josesaid.develop.compras.domain.Recepcion;\nimport com.mx.josesaid.develop.compras.domain.RecepcionRepositorio;\nimport com.mx.josesaid.develop.compras.domain.RecursoNoEncontradoException;\nimport com.mx.josesaid.develop.compras.domain.ResumenOrdenCompra;\nimport com.mx.josesaid.develop.compras.domain.SolicitudInvalidaException;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n/** Casos de uso de compras. Cada cambio de estado relevante se publica por outbox en la misma transacción. */\n@Service\npublic class ComprasService {\n\n    public static final String EVENTO_ORDEN_APROBADA = \"orden-compra-aprobada\";\n    public static final String EVENTO_INSUMOS_RECIBIDOS = \"insumos-recibidos\";\n    /** Límite fijo del listado de órdenes para las herramientas de IA y la API. */\n    public static final int LIMITE_LISTADO_ORDENES = 15;\n\n    /**\n     * Fila del listado: sin RFC, sin montos y sin líneas.\n     *\n     * @param id identificador único del registro, de tipo {@code UUID}.\n     * @param estatus estado actual del registro, de tipo {@code EstatusOrdenCompra}.\n     * @param razonSocialProveedor razon social proveedor, de tipo {@code String}.\n     * @param creadaUtc creada utc, de tipo {@code Instant}.\n     */\n    public record ResumenListado(UUID id, EstatusOrdenCompra estatus, String razonSocialProveedor, Instant creadaUtc) {\n    }\n\n    private final ProveedorRepositorio proveedores;\n    private final OrdenCompraRepositorio ordenes;\n    private final RecepcionRepositorio recepciones;\n    private final PublicadorEventos eventos;\n    private final BigDecimal tipoCambioMxnPorUsd;\n    private final BigDecimal limiteAprobacionUsd;\n\n    /** Recibe los repositorios de proveedores, órdenes y recepciones, el publicador de eventos, el reloj y los parámetros de aprobación por monto. */\n    public ComprasService(ProveedorRepositorio proveedores, OrdenCompraRepositorio ordenes,\n                          RecepcionRepositorio recepciones, PublicadorEventos eventos,\n                          @Value(\"${compras.tipo-cambio-mxn-por-usd:18}\") BigDecimal tipoCambioMxnPorUsd,\n                          @Value(\"${compras.limite-aprobacion-usd:1000000}\") BigDecimal limiteAprobacionUsd) {\n        if (limiteAprobacionUsd.signum() <= 0 || limiteAprobacionUsd.stripTrailingZeros().scale() > 0) {\n            throw new IllegalArgumentException(\"compras.limite-aprobacion-usd debe ser un monto entero mayor a cero en USD\");\n        }\n        this.proveedores = proveedores;\n        this.ordenes = ordenes;\n        this.recepciones = recepciones;\n        this.eventos = eventos;\n        this.tipoCambioMxnPorUsd = tipoCambioMxnPorUsd;\n        this.limiteAprobacionUsd = limiteAprobacionUsd;\n    }\n\n    /** Da de alta un proveedor. Rechaza el RFC si ya está registrado. */\n    @Transactional\n    public Proveedor crearProveedor(String razonSocial, String rfc, String correo) {\n        Proveedor proveedor = Proveedor.crear(razonSocial, rfc, correo);\n        if (proveedores.existePorRfc(proveedor.getRfc())) {\n            throw new ConflictoException(\"Ya existe un proveedor con ese RFC\");\n        }\n        return proveedores.guardar(proveedor);\n    }\n\n    /** Busca proveedores por texto en la razón social. */\n    @Transactional(readOnly = true)\n    public List<Proveedor> buscarProveedores(String texto) {\n        String termino = texto == null ? \"\" : texto.trim();\n        if (termino.length() < 3) {\n            throw new SolicitudInvalidaException(\"La búsqueda requiere al menos 3 caracteres\");\n        }\n        return proveedores.buscarPorRazonSocial(termino);\n    }\n\n    /** Devuelve un proveedor por id o lanza RecursoNoEncontradoException. */\n    public Proveedor obtenerProveedor(UUID id) {\n        return proveedores.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Proveedor no encontrado: \" + id));\n    }\n\n    /** Crea una orden de compra en borrador y guarda quién la creó. */\n    @Transactional\n    public OrdenCompra crearOrden(UUID proveedorId, String moneda, List<LineaOrden> lineas, String creadaPor) {\n        Proveedor proveedor = obtenerProveedor(proveedorId);\n        return ordenes.guardar(OrdenCompra.crear(proveedor, moneda, lineas, creadaPor));\n    }\n\n    /** Lista las órdenes recientes, opcionalmente filtradas por estatus. */\n    @Transactional(readOnly = true)\n    public List<ResumenListado> listarOrdenesRecientes(EstatusOrdenCompra estatus) {\n        return ordenes.listarRecientes(estatus, LIMITE_LISTADO_ORDENES).stream()\n                .map(r -> new ResumenListado(r.id(), r.estatus(),\n                        proveedores.buscarPorId(r.proveedorId()).map(Proveedor::getRazonSocial).orElse(\"\"),\n                        r.creadaUtc()))\n                .toList();\n    }\n\n    /** Devuelve una orden por id o lanza RecursoNoEncontradoException. */\n    @Transactional(readOnly = true)\n    public OrdenCompra obtenerOrden(UUID id) {\n        return ordenes.buscarPorId(id)\n                .orElseThrow(() -> new RecursoNoEncontradoException(\"Orden de compra no encontrada: \" + id));\n    }\n\n    /** Aprueba la orden y publica el evento de aprobación con su total. Las reglas de quién puede aprobar están en OrdenCompra.aprobar. */\n    @Transactional\n    public OrdenCompra aprobarOrden(UUID id, String usuario, boolean esDireccion) {\n        OrdenCompra orden = obtenerOrden(id);\n        orden.aprobar(usuario, esDireccion, tipoCambioMxnPorUsd, limiteAprobacionUsd);\n        OrdenCompra guardada = ordenes.guardar(orden);\n        eventos.publicar(new EventoDominio(EVENTO_ORDEN_APROBADA, id.toString(), Map.of(\n                \"id\", id.toString(),\n                \"proveedor_id\", guardada.getProveedorId().toString(),\n                \"moneda\", guardada.getMoneda(),\n                \"total\", guardada.total().toPlainString())));\n        return guardada;\n    }\n\n    /** Registra una o más líneas recibidas. Si una línea falla, toda la recepción se revierte. */\n    @Transactional\n    public OrdenCompra registrarRecepcion(UUID id, List<LineaRecibida> lineas) {\n        OrdenCompra orden = obtenerOrden(id);\n        List<Map<String, Object>> detalle = new java.util.ArrayList<>();\n        for (LineaRecibida linea : lineas) {\n            Recepcion recepcion = orden.recibir(linea.sku(), linea.cantidad());\n            recepciones.guardar(recepcion);\n            detalle.add(Map.of(\"sku\", linea.sku(), \"cantidad\", recepcion.cantidad().toPlainString()));\n        }\n        OrdenCompra guardada = ordenes.guardar(orden);\n        eventos.publicar(new EventoDominio(EVENTO_INSUMOS_RECIBIDOS, id.toString(), Map.of(\n                \"evento_id\", UUID.randomUUID().toString(),\n                \"orden_id\", id.toString(),\n                \"lineas\", detalle)));\n        return guardada;\n    }\n\n    /** Cancela la orden con su motivo. */\n    @Transactional\n    public OrdenCompra cancelarOrden(UUID id, String motivo) {\n        OrdenCompra orden = obtenerOrden(id);\n        orden.cancelar(motivo);\n        return ordenes.guardar(orden);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/application/EventoDominio.java": "package com.mx.josesaid.develop.compras.application;\n\nimport java.util.Map;\n\n/**\n * Evento de negocio. Se guarda en el outbox y luego se envía a Kafka.\n *\n * @param tipo tipo o clasificación del registro, de tipo {@code String}.\n * @param agregadoId identificador del agregado de dominio al que pertenece el evento, de tipo {@code String}.\n * @param datos datos específicos de la operación, de tipo {@code Map<String, Object>}.\n */\npublic record EventoDominio(String tipo, String agregadoId, Map<String, Object> datos) {\n}\n", "src/main/java/com/mx/josesaid/develop/compras/application/LineaRecibida.java": "package com.mx.josesaid.develop.compras.application;\n\nimport java.math.BigDecimal;\n\n/**\n * Una línea de una recepción: SKU y cantidad recibida.\n *\n * @param sku clave SKU del artículo, de tipo {@code String}.\n * @param cantidad cantidad solicitada o registrada, de tipo {@code BigDecimal}.\n */\npublic record LineaRecibida(String sku, BigDecimal cantidad) {\n}\n", "src/main/java/com/mx/josesaid/develop/compras/application/PublicadorEventos.java": "package com.mx.josesaid.develop.compras.application;\n\n/** Publica eventos de dominio de compras para que otros servicios reaccionen. */\npublic interface PublicadorEventos {\n    void publicar(EventoDominio evento);\n}\n", "src/main/java/com/mx/josesaid/develop/compras/config/PropiedadesJwt.java": "package com.mx.josesaid.develop.compras.config;\n\nimport java.time.Duration;\nimport org.springframework.boot.context.properties.ConfigurationProperties;\n\n/**\n * Propiedades del emisor de tokens, enlazadas desde {@code compras.jwt}.\n *\n * @param jwksUri URL del JWKS de usuarios-accesos-ms con la clave pública para validar tokens\n * @param duracion vida del token de acceso\n * @param emisor   valor del claim {@code iss}\n */\n@ConfigurationProperties(prefix = \"compras.jwt\")\npublic record PropiedadesJwt(String jwksUri, Duration duracion, String emisor) {\n}\n", "src/main/java/com/mx/josesaid/develop/compras/config/RelojConfig.java": "package com.mx.josesaid.develop.compras.config;\n\nimport java.time.Clock;\nimport java.time.ZoneId;\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\n\n/** Reloj en UTC. Inyectarlo permite probar las reglas de tiempo sin depender de la hora real. */\n@Configuration\npublic class RelojConfig {\n\n    /** Reloj del sistema en UTC, usado para las fechas de compras. */\n    @Bean\n    Clock reloj() {\n        return Clock.system(ZoneId.of(\"America/Mexico_City\"));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/config/SeguridadConfig.java": "package com.mx.josesaid.develop.compras.config;\n\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchy;\nimport org.springframework.security.access.hierarchicalroles.RoleHierarchyImpl;\n\nimport com.mx.josesaid.develop.compras.seguridad.EntradaNoAutorizada;\n\nimport com.mx.josesaid.develop.compras.seguridad.RevocacionSesiones;\nimport com.mx.josesaid.develop.compras.seguridad.ValidadorRevocacion;\nimport org.springframework.security.oauth2.core.DelegatingOAuth2TokenValidator;\nimport org.springframework.security.oauth2.jwt.JwtValidators;\n\nimport org.springframework.context.annotation.Bean;\nimport org.springframework.context.annotation.Configuration;\nimport org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;\nimport org.springframework.security.config.annotation.web.builders.HttpSecurity;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.config.http.SessionCreationPolicy;\nimport org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;\nimport org.springframework.security.crypto.password.PasswordEncoder;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.security.oauth2.jwt.NimbusJwtDecoder;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;\nimport org.springframework.security.oauth2.server.resource.authentication.JwtGrantedAuthoritiesConverter;\nimport org.springframework.security.web.SecurityFilterChain;\n\n/**\n * Seguridad del servicio: API sin estado, JWT como resource server y autorización por rol.\n *\n * <p>Solo el login y el health son públicos. Todo lo demás exige un token válido.\n */\n@Configuration\n@EnableWebSecurity\n@EnableMethodSecurity\npublic class SeguridadConfig {\n\n    /** Cadena de seguridad de la API sin estado. Exige JWT válido en todo, excepto salud, info y métricas. */\n    @Bean\n    SecurityFilterChain cadenaSeguridad(HttpSecurity http) throws Exception {\n        http\n            .csrf(csrf -> csrf.disable()) // API sin cookies de sesión: no aplica CSRF\n            .sessionManagement(sesion -> sesion.sessionCreationPolicy(SessionCreationPolicy.STATELESS))\n            .authorizeHttpRequests(auth -> auth\n                .requestMatchers(\"/actuator/health\", \"/actuator/health/**\", \"/actuator/prometheus\").permitAll()\n                .anyRequest().authenticated())\n            .oauth2ResourceServer(oauth -> oauth.authenticationEntryPoint(new EntradaNoAutorizada()).jwt(jwt -> jwt.jwtAuthenticationConverter(convertidorJwt())));\n        return http.build();\n    }\n\n    /** Convierte el claim {@code roles} en autoridades {@code ROLE_*}. */\n    @Bean\n    JwtAuthenticationConverter convertidorJwt() {\n        JwtGrantedAuthoritiesConverter autoridades = new JwtGrantedAuthoritiesConverter();\n        autoridades.setAuthoritiesClaimName(\"roles\");\n        autoridades.setAuthorityPrefix(\"ROLE_\");\n        JwtAuthenticationConverter convertidor = new JwtAuthenticationConverter();\n        convertidor.setJwtGrantedAuthoritiesConverter(autoridades);\n        return convertidor;\n    }\n\n    /** Valida la firma con la clave pública que publica usuarios-accesos-ms (JWKS). */\n    @Bean\n    JwtDecoder jwtDecoder(PropiedadesJwt propiedades, RevocacionSesiones revocaciones) {\n        var decoder = NimbusJwtDecoder.withJwkSetUri(propiedades.jwksUri()).build();\n        decoder.setJwtValidator(new DelegatingOAuth2TokenValidator<>(JwtValidators.createDefault(),\n                new ValidadorRevocacion(revocaciones)));\n        return decoder;\n    }\n\n    /** Codificador de contraseñas BCrypt. */\n    @Bean\n    PasswordEncoder passwordEncoder() {\n        return new BCryptPasswordEncoder();\n    }\n\n    /** ADMIN puede hacer todo: hereda todos los roles de negocio. */\n    @Bean\n    RoleHierarchy jerarquiaRoles() {\n        return RoleHierarchyImpl.withDefaultRolePrefix()\n                .role(\"ADMIN\").implies(\"FINANZAS\", \"CONTADOR\", \"VENTAS\", \"COMPRAS\", \"ALMACEN\", \"OPERACIONES\", \"CALIDAD\", \"DIRECCION\", \"LEGAL\", \"JEFE_AREA\")\n                .build();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/AprobacionNoPermitidaException.java": "package com.mx.josesaid.develop.compras.domain;\n\n/** El usuario no puede aprobar esta orden por segregación de funciones o por su monto. HTTP 403. */\npublic class AprobacionNoPermitidaException extends RuntimeException {\n    /** Se lanza cuando el usuario no puede aprobar la orden: por ser quien la creó, por el límite de monto o por ser una orden sin creador registrado. */\n    public AprobacionNoPermitidaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/ConflictoException.java": "package com.mx.josesaid.develop.compras.domain;\n\n/** Conflicto con el estado actual, por ejemplo recepción mayor a lo ordenado. HTTP 409. */\npublic class ConflictoException extends RuntimeException {\n    /** Se lanza cuando la operación choca con el estado actual. Se responde como conflicto. */\n    public ConflictoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/EstatusOrdenCompra.java": "package com.mx.josesaid.develop.compras.domain;\n\n/** BORRADOR → APROBADA → RECIBIDA_PARCIAL → RECIBIDA. CANCELADA se alcanza desde BORRADOR o APROBADA. */\npublic enum EstatusOrdenCompra { BORRADOR, APROBADA, RECIBIDA_PARCIAL, RECIBIDA, CANCELADA }\n", "src/main/java/com/mx/josesaid/develop/compras/domain/EstatusProveedor.java": "package com.mx.josesaid.develop.compras.domain;\n\n/** Estatus del proveedor: activo, inactivo o bloqueado. */\npublic enum EstatusProveedor { ACTIVO, INACTIVO, BLOQUEADO }\n", "src/main/java/com/mx/josesaid/develop/compras/domain/LineaOrden.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport static java.math.BigDecimal.ZERO;\n\nimport java.math.BigDecimal;\nimport java.math.RoundingMode;\n\n/** Línea de una orden: lo ordenado, lo recibido hasta ahora y el precio pactado. */\npublic final class LineaOrden {\n\n    private final String articuloSku;\n    private final BigDecimal cantidadOrdenada;\n    private final BigDecimal cantidadRecibida;\n    private final BigDecimal precioUnitario;\n\n    /** Constructor privado: las líneas se crean con sus fábricas. */\n    private LineaOrden(String articuloSku, BigDecimal cantidadOrdenada, BigDecimal cantidadRecibida,\n                       BigDecimal precioUnitario) {\n        this.articuloSku = articuloSku;\n        this.cantidadOrdenada = cantidadOrdenada;\n        this.cantidadRecibida = cantidadRecibida;\n        this.precioUnitario = precioUnitario;\n    }\n\n    /** Crea una línea nueva con cantidad y precio. La cantidad recibida empieza en cero. */\n    public static LineaOrden nueva(String sku, BigDecimal cantidad, BigDecimal precioUnitario) {\n        if (sku == null || sku.isBlank()) {\n            throw new ReglaDeNegocioException(\"Cada línea requiere SKU\");\n        }\n        if (cantidad == null || cantidad.signum() <= 0) {\n            throw new ReglaDeNegocioException(\"La cantidad de cada línea debe ser mayor a cero\");\n        }\n        if (precioUnitario == null || precioUnitario.signum() < 0) {\n            throw new ReglaDeNegocioException(\"El precio unitario no puede ser negativo\");\n        }\n        return new LineaOrden(sku.trim(), cantidad.setScale(3, RoundingMode.HALF_EVEN), ZERO,\n                precioUnitario.setScale(2, RoundingMode.HALF_EVEN));\n    }\n\n    /** Reconstruye una línea desde la base de datos sin aplicar reglas. */\n    public static LineaOrden reconstruir(String sku, BigDecimal ordenada, BigDecimal recibida, BigDecimal precio) {\n        return new LineaOrden(sku, ordenada, recibida, precio);\n    }\n\n    /** Devuelve una copia con la cantidad recibida incrementada. */\n    LineaOrden conRecepcion(BigDecimal cantidad) {\n        return new LineaOrden(articuloSku, cantidadOrdenada, cantidadRecibida.add(cantidad), precioUnitario);\n    }\n\n    /** Devuelve el subtotal: cantidad ordenada por precio unitario. */\n    public BigDecimal subtotal() {\n        return cantidadOrdenada.multiply(precioUnitario).setScale(2, RoundingMode.HALF_EVEN);\n    }\n\n    /** Indica si ya se recibió toda la cantidad ordenada. */\n    public boolean completa() {\n        return cantidadRecibida.compareTo(cantidadOrdenada) >= 0;\n    }\n\n    /** Devuelve el SKU del artículo. */\n    public String getArticuloSku() { return articuloSku; }\n    /** Devuelve la cantidad ordenada. */\n    public BigDecimal getCantidadOrdenada() { return cantidadOrdenada; }\n    /** Devuelve la cantidad recibida. */\n    public BigDecimal getCantidadRecibida() { return cantidadRecibida; }\n    /** Devuelve el precio unitario. */\n    public BigDecimal getPrecioUnitario() { return precioUnitario; }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/OrdenCompra.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport static java.math.BigDecimal.ZERO;\n\nimport java.math.BigDecimal;\nimport java.math.RoundingMode;\nimport java.util.ArrayList;\nimport java.util.Collections;\nimport java.util.List;\nimport java.util.Locale;\nimport java.util.UUID;\n\n/**\n * Orden de compra. Una orden aprobada no se modifica: solo se recibe o se cancela.\n * La recepción no puede superar lo ordenado (409).\n */\npublic class OrdenCompra {\n\n    private static final java.util.Set<String> MONEDAS = java.util.Set.of(\"MXN\", \"USD\");\n\n    private final UUID id;\n    private final UUID proveedorId;\n    private final String moneda;\n    private EstatusOrdenCompra estatus;\n    private String motivoCancelacion;\n    private final List<LineaOrden> lineas;\n    private final String creadaPor;\n\n    /** Constructor privado: las órdenes se crean con sus fábricas. */\n    private OrdenCompra(UUID id, UUID proveedorId, String moneda, EstatusOrdenCompra estatus,\n                        String motivoCancelacion, List<LineaOrden> lineas, String creadaPor) {\n        this.id = id;\n        this.proveedorId = proveedorId;\n        this.moneda = moneda;\n        this.estatus = estatus;\n        this.motivoCancelacion = motivoCancelacion;\n        this.lineas = new ArrayList<>(lineas);\n        this.creadaPor = creadaPor;\n    }\n\n    /** Crea la orden en BORRADOR. Un proveedor inactivo no recibe órdenes nuevas (422). */\n    public static OrdenCompra crear(Proveedor proveedor, String moneda, List<LineaOrden> lineas, String creadaPor) {\n        if (proveedor == null) {\n            throw new RecursoNoEncontradoException(\"Proveedor no encontrado\");\n        }\n        if (!proveedor.estaActivo()) {\n            throw new ReglaDeNegocioException(\"El proveedor no está activo y no recibe órdenes nuevas\");\n        }\n        if (moneda == null || !MONEDAS.contains(moneda)) {\n            throw new ReglaDeNegocioException(\"La moneda no está permitida: \" + moneda);\n        }\n        if (lineas == null || lineas.isEmpty()) {\n            throw new ReglaDeNegocioException(\"La orden requiere al menos una línea\");\n        }\n        if (creadaPor == null || creadaPor.isBlank()) {\n            throw new ReglaDeNegocioException(\"La orden necesita el usuario que la crea\");\n        }\n        return new OrdenCompra(UUID.randomUUID(), proveedor.getId(), moneda, EstatusOrdenCompra.BORRADOR, null, lineas, creadaPor);\n    }\n\n    /** Reconstruye una orden desde la base de datos sin aplicar reglas de aprobación. */\n    public static OrdenCompra reconstruir(UUID id, UUID proveedorId, String moneda, EstatusOrdenCompra estatus,\n                                          String motivoCancelacion, List<LineaOrden> lineas, String creadaPor) {\n        return new OrdenCompra(id, proveedorId, moneda, estatus, motivoCancelacion, lineas, creadaPor);\n    }\n\n    /**\n     * Aprueba la orden si el usuario puede hacerlo:\n     * nadie aprueba una orden que creó; las que igualan o superan el límite de aprobación solo las aprueba DIRECCION;\n     * las órdenes antiguas, sin creador registrado, solo las aprueba DIRECCION.\n     */\n    public void aprobar(String usuario, boolean esDireccion, BigDecimal tipoCambioMxnPorUsd,\n                        BigDecimal limiteAprobacionUsd) {\n        if (estatus != EstatusOrdenCompra.BORRADOR) {\n            throw new ConflictoException(\"Solo una orden en borrador puede aprobarse\");\n        }\n        if (creadaPor == null) {\n            if (!esDireccion) {\n                throw new AprobacionNoPermitidaException(\n                        \"Esta orden se creó antes de registrar su creador; solo DIRECCION puede aprobarla\");\n            }\n        } else if (creadaPor.equals(usuario)) {\n            throw new AprobacionNoPermitidaException(\"No puedes aprobar una orden que tú creaste\");\n        } else if (!esDireccion && totalEnUsd(tipoCambioMxnPorUsd).compareTo(limiteAprobacionUsd) >= 0) {\n            throw new AprobacionNoPermitidaException(\n                    \"Las órdenes de \" + String.format(Locale.US, \"%,d\", limiteAprobacionUsd.toBigInteger()) + \" USD o más solo puede aprobarlas DIRECCION\");\n        }\n        this.estatus = EstatusOrdenCompra.APROBADA;\n    }\n\n    /** Total en USD para comparar contra el límite. Las órdenes en MXN se convierten con el tipo de cambio. */\n    public BigDecimal totalEnUsd(BigDecimal tipoCambioMxnPorUsd) {\n        if (\"USD\".equals(moneda)) {\n            return total();\n        }\n        return total().divide(tipoCambioMxnPorUsd, 2, RoundingMode.HALF_UP);\n    }\n\n    /** Registra una recepción de una línea. Devuelve la recepción para su historial. */\n    public Recepcion recibir(String sku, BigDecimal cantidad) {\n        if (estatus != EstatusOrdenCompra.APROBADA && estatus != EstatusOrdenCompra.RECIBIDA_PARCIAL) {\n            throw new ConflictoException(\"Solo una orden aprobada admite recepciones\");\n        }\n        if (cantidad == null || cantidad.signum() <= 0) {\n            throw new ReglaDeNegocioException(\"La cantidad recibida debe ser mayor a cero\");\n        }\n        int indice = indiceDe(sku);\n        LineaOrden linea = lineas.get(indice);\n        BigDecimal cantidadRedondeada = cantidad.setScale(3, RoundingMode.HALF_EVEN);\n        BigDecimal pendiente = linea.getCantidadOrdenada().subtract(linea.getCantidadRecibida());\n        if (cantidadRedondeada.compareTo(pendiente) > 0) {\n            throw new ConflictoException(\"La recepción excede lo ordenado para \" + sku\n                    + \": pendiente \" + pendiente.toPlainString());\n        }\n        lineas.set(indice, linea.conRecepcion(cantidadRedondeada));\n        this.estatus = lineas.stream().allMatch(LineaOrden::completa)\n                ? EstatusOrdenCompra.RECIBIDA : EstatusOrdenCompra.RECIBIDA_PARCIAL;\n        return new Recepcion(UUID.randomUUID(), id, sku, cantidadRedondeada);\n    }\n\n    /** Cancela la orden en borrador o aprobada. El motivo es obligatorio. */\n    public void cancelar(String motivo) {\n        if (motivo == null || motivo.isBlank()) {\n            throw new SolicitudInvalidaException(\"El motivo de cancelación es obligatorio\");\n        }\n        if (estatus != EstatusOrdenCompra.BORRADOR && estatus != EstatusOrdenCompra.APROBADA) {\n            throw new ConflictoException(\"Solo una orden en borrador o aprobada puede cancelarse\");\n        }\n        this.estatus = EstatusOrdenCompra.CANCELADA;\n        this.motivoCancelacion = motivo.trim();\n    }\n\n    /** Devuelve la suma de los subtotales de las líneas. */\n    public BigDecimal total() {\n        return lineas.stream().map(LineaOrden::subtotal).reduce(ZERO, BigDecimal::add);\n    }\n\n    /** Devuelve la posición de la línea con ese SKU. Falla si la orden no contiene el SKU. */\n    private int indiceDe(String sku) {\n        for (int i = 0; i < lineas.size(); i++) {\n            if (lineas.get(i).getArticuloSku().equals(sku)) {\n                return i;\n            }\n        }\n        throw new ReglaDeNegocioException(\"La orden no contiene el SKU \" + sku);\n    }\n\n    /** Devuelve el usuario que creó la orden, o nulo en órdenes antiguas. */\n    public String getCreadaPor() { return creadaPor; }\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve el id del proveedor. */\n    public UUID getProveedorId() { return proveedorId; }\n    /** Devuelve la moneda. */\n    public String getMoneda() { return moneda; }\n    /** Devuelve el estatus. */\n    public EstatusOrdenCompra getEstatus() { return estatus; }\n    /** Devuelve el motivo de cancelación, o nulo. */\n    public String getMotivoCancelacion() { return motivoCancelacion; }\n    /** Devuelve las líneas, en una vista de solo lectura. */\n    public List<LineaOrden> getLineas() { return Collections.unmodifiableList(lineas); }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/OrdenCompraRepositorio.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar órdenes de compra, sin depender de JPA. */\npublic interface OrdenCompraRepositorio {\n    OrdenCompra guardar(OrdenCompra orden);\n    Optional<OrdenCompra> buscarPorId(UUID id);\n    /** Órdenes más recientes primero; estatus opcional (null = todos). */\n    List<ResumenOrdenCompra> listarRecientes(EstatusOrdenCompra estatus, int limite);\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/Proveedor.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport java.util.Locale;\nimport java.util.UUID;\nimport java.util.regex.Pattern;\n\n/**\n * Proveedor. En el dominio los datos fiscales viven en claro; la infraestructura los cifra al guardarlos.\n * El RFC sigue el formato de personas morales (3 letras) o físicas (4 letras), más fecha y homoclave.\n */\npublic class Proveedor {\n\n    private static final Pattern RFC = Pattern.compile(\"^[A-ZÑ&]{3,4}[0-9]{6}[A-Z0-9]{3}$\");\n    private static final Pattern CORREO = Pattern.compile(\"^[^@\\\\s]+@[^@\\\\s]+\\\\.[^@\\\\s]+$\");\n\n    private final UUID id;\n    private final String razonSocial;\n    private final String rfc;\n    private final String correo;\n    private final EstatusProveedor estatus;\n\n    /** Constructor privado: los proveedores se crean con sus fábricas. */\n    private Proveedor(UUID id, String razonSocial, String rfc, String correo, EstatusProveedor estatus) {\n        this.id = id;\n        this.razonSocial = razonSocial;\n        this.rfc = rfc;\n        this.correo = correo;\n        this.estatus = estatus;\n    }\n\n    /** Crea un proveedor nuevo con sus datos de contacto. */\n    public static Proveedor crear(String razonSocial, String rfc, String correo) {\n        if (razonSocial == null || razonSocial.isBlank()) {\n            throw new ReglaDeNegocioException(\"La razón social es obligatoria\");\n        }\n        String rfcNormalizado = rfc == null ? \"\" : rfc.trim().toUpperCase(Locale.ROOT);\n        if (!RFC.matcher(rfcNormalizado).matches()) {\n            throw new ReglaDeNegocioException(\"El RFC no tiene un formato válido\");\n        }\n        String correoNormalizado = correo == null ? \"\" : correo.trim().toLowerCase(Locale.ROOT);\n        if (!CORREO.matcher(correoNormalizado).matches()) {\n            throw new ReglaDeNegocioException(\"El correo no tiene un formato válido\");\n        }\n        return new Proveedor(UUID.randomUUID(), razonSocial.trim(), rfcNormalizado, correoNormalizado,\n                EstatusProveedor.ACTIVO);\n    }\n\n    /** Reconstruye un proveedor desde la base de datos sin validar. */\n    public static Proveedor reconstruir(UUID id, String razonSocial, String rfc, String correo, EstatusProveedor estatus) {\n        return new Proveedor(id, razonSocial, rfc, correo, estatus);\n    }\n\n    /** Devuelve el identificador. */\n    public UUID getId() { return id; }\n    /** Devuelve la razón social. */\n    public String getRazonSocial() { return razonSocial; }\n    /** Devuelve el RFC. */\n    public String getRfc() { return rfc; }\n    /** Devuelve el correo de contacto. */\n    public String getCorreo() { return correo; }\n    /** Devuelve el estatus. */\n    public EstatusProveedor getEstatus() { return estatus; }\n    /** Indica si el proveedor está en estatus activo. */\n    public boolean estaActivo() { return estatus == EstatusProveedor.ACTIVO; }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/ProveedorRepositorio.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\n\n/** Puerto para guardar y consultar proveedores, sin depender de JPA. */\npublic interface ProveedorRepositorio {\n    Proveedor guardar(Proveedor proveedor);\n    Optional<Proveedor> buscarPorId(UUID id);\n    boolean existePorRfc(String rfc);\n    List<Proveedor> buscarPorRazonSocial(String texto);\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/Recepcion.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/**\n * Registro de una recepción. Es histórico: no se modifica ni se borra.\n *\n * @param id identificador único del registro, de tipo {@code UUID}.\n * @param ordenId identificador del orden, de tipo {@code UUID}.\n * @param articuloSku articulo sku, de tipo {@code String}.\n * @param cantidad cantidad solicitada o registrada, de tipo {@code BigDecimal}.\n */\npublic record Recepcion(UUID id, UUID ordenId, String articuloSku, BigDecimal cantidad) {\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/RecepcionRepositorio.java": "package com.mx.josesaid.develop.compras.domain;\n\n/** Puerto para guardar las recepciones de mercancía, sin depender de JPA. */\npublic interface RecepcionRepositorio {\n    Recepcion guardar(Recepcion recepcion);\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/RecursoNoEncontradoException.java": "package com.mx.josesaid.develop.compras.domain;\n\n/** El recurso no existe. HTTP 404. */\npublic class RecursoNoEncontradoException extends RuntimeException {\n    /** Se lanza cuando no existe el recurso pedido. */\n    public RecursoNoEncontradoException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/ReglaDeNegocioException.java": "package com.mx.josesaid.develop.compras.domain;\n\n/** Una operación viola una regla de negocio. HTTP 422. */\npublic class ReglaDeNegocioException extends RuntimeException {\n    /** Se lanza cuando una regla de negocio no se cumple. El mensaje se muestra al cliente. */\n    public ReglaDeNegocioException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/ResumenOrdenCompra.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport java.time.Instant;\nimport java.util.UUID;\n\n/**\n * Datos de una orden que el listado necesita: sin líneas ni montos.\n *\n * @param id identificador único del registro, de tipo {@code UUID}.\n * @param proveedorId identificador del proveedor, de tipo {@code UUID}.\n * @param estatus estado actual del registro, de tipo {@code EstatusOrdenCompra}.\n * @param creadaUtc creada utc, de tipo {@code Instant}.\n */\npublic record ResumenOrdenCompra(UUID id, UUID proveedorId, EstatusOrdenCompra estatus, Instant creadaUtc) {\n}\n", "src/main/java/com/mx/josesaid/develop/compras/domain/SolicitudInvalidaException.java": "package com.mx.josesaid.develop.compras.domain;\n\n/** Solicitud con datos de forma inválidos, como motivo vacío. HTTP 400. */\npublic class SolicitudInvalidaException extends RuntimeException {\n    /** Se lanza cuando la solicitud no es válida. */\n    public SolicitudInvalidaException(String mensaje) {\n        super(mensaje);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/idempotencia/Idempotencia.java": "package com.mx.josesaid.develop.compras.infrastructure.idempotencia;\n\nimport com.fasterxml.jackson.core.JsonProcessingException;\nimport com.fasterxml.jackson.databind.ObjectMapper;\nimport com.mx.josesaid.develop.compras.domain.ConflictoException;\nimport com.mx.josesaid.develop.compras.domain.ReglaDeNegocioException;\nimport java.nio.charset.StandardCharsets;\nimport java.security.MessageDigest;\nimport java.security.NoSuchAlgorithmException;\nimport java.util.HexFormat;\nimport java.util.function.Supplier;\nimport org.springframework.http.HttpStatus;\nimport org.springframework.http.MediaType;\nimport org.springframework.http.ResponseEntity;\nimport org.springframework.stereotype.Component;\n\n/**\n * Hace seguras de reintentar las altas que reciben la cabecera Idempotency-Key.\n * Misma clave y misma petición: devuelve la respuesta original, sin crear nada nuevo.\n * Misma clave con otra petición: 422. Clave todavía en proceso: 409.\n * Sin cabecera: la operación se ejecuta como siempre.\n */\n@Component\npublic class Idempotencia {\n\n    public static final String CABECERA = \"Idempotency-Key\";\n\n    private final RegistroIdempotencia registro;\n    private final ObjectMapper mapper;\n\n    /** Recibe el registro de claves y el serializador JSON. */\n    public Idempotencia(RegistroIdempotencia registro, ObjectMapper mapper) {\n        this.registro = registro;\n        this.mapper = mapper;\n    }\n\n    /** Ejecuta una operación una sola vez por Idempotency-Key. Una misma clave con la misma petición devuelve la respuesta guardada; con otra petición, rechaza. Si la operación falla, libera la clave para reintentar. */\n    public <T> ResponseEntity<?> ejecutar(String clave, String ruta, Object peticion,\n                                          HttpStatus estado, Supplier<T> operacion) {\n        if (clave == null || clave.isBlank()) {\n            return ResponseEntity.status(estado).body(operacion.get());\n        }\n        String huella = huella(ruta, peticion);\n        if (!registro.reservar(clave, huella)) {\n            RegistroIdempotencia.Registro previo = registro.buscar(clave)\n                    .orElseThrow(() -> new ConflictoException(\"La Idempotency-Key ya no está disponible. Intente de nuevo.\"));\n            if (!previo.huella().equals(huella)) {\n                throw new ReglaDeNegocioException(\"La Idempotency-Key ya se usó con una petición distinta.\");\n            }\n            if (!previo.completada()) {\n                throw new ConflictoException(\"La petición con esta Idempotency-Key aún se está procesando.\");\n            }\n            return ResponseEntity.status(previo.estatus())\n                    .contentType(MediaType.APPLICATION_JSON)\n                    .body(previo.cuerpo());\n        }\n        T cuerpo;\n        try {\n            cuerpo = operacion.get();\n        } catch (RuntimeException e) {\n            registro.liberar(clave);\n            throw e;\n        }\n        registro.completar(clave, estado.value(), serializar(cuerpo));\n        return ResponseEntity.status(estado).body(cuerpo);\n    }\n\n    /** Calcula la huella SHA-256 de la ruta y el cuerpo de la petición, para detectar si una clave se reutiliza con otra petición. */\n    private String huella(String ruta, Object peticion) {\n        try {\n            byte[] digest = MessageDigest.getInstance(\"SHA-256\")\n                    .digest((ruta + \"\\n\" + mapper.writeValueAsString(peticion)).getBytes(StandardCharsets.UTF_8));\n            return HexFormat.of().formatHex(digest);\n        } catch (JsonProcessingException | NoSuchAlgorithmException e) {\n            throw new IllegalStateException(\"No se pudo calcular la huella de la petición\", e);\n        }\n    }\n\n    /** Convierte la respuesta en JSON para guardarla. */\n    private String serializar(Object cuerpo) {\n        try {\n            return mapper.writeValueAsString(cuerpo);\n        } catch (JsonProcessingException e) {\n            throw new IllegalStateException(\"No se pudo guardar la respuesta idempotente\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/idempotencia/RegistroIdempotencia.java": "package com.mx.josesaid.develop.compras.infrastructure.idempotencia;\n\nimport java.sql.Timestamp;\nimport java.time.Clock;\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Optional;\nimport org.springframework.dao.DuplicateKeyException;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Repository;\n\n/**\n * Guarda el estado de cada clave Idempotency-Key. Una respuesta completada se conserva 24 horas.\n * Una reserva que nunca se completó (la petición murió a medio camino) se puede retomar tras\n * {@link #CONCESION_RESERVA}, para que la clave no quede bloqueada todo el día.\n */\n@Repository\nclass RegistroIdempotencia {\n\n    static final Duration VIGENCIA = Duration.ofHours(24);\n    static final Duration CONCESION_RESERVA = Duration.ofMinutes(2);\n\n    /**\n     * Fila guardada para una clave: huella, estatus HTTP, cuerpo de la respuesta y si ya terminó.\n     *\n     * @param huella huella, de tipo {@code String}.\n     * @param estatus estado actual del registro, de tipo {@code int}.\n     * @param cuerpo contenido principal del mensaje, de tipo {@code String}.\n     * @param completada completada, de tipo {@code boolean}.\n     */\n    record Registro(String huella, int estatus, String cuerpo, boolean completada) {}\n\n    private final JdbcTemplate jdbc;\n    private final Clock reloj;\n\n    RegistroIdempotencia(JdbcTemplate jdbc, Clock reloj) {\n        this.jdbc = jdbc;\n        this.reloj = reloj;\n    }\n\n    /** Busca el registro de una clave que sigue vigente. */\n    Optional<Registro> buscar(String clave) {\n        return jdbc.query(\n                \"SELECT huella, estatus_http, cuerpo, completada FROM idempotencia WHERE clave = ? AND creado_utc > ?\",\n                (rs, n) -> new Registro(rs.getString(1), rs.getInt(2), rs.getString(3), rs.getBoolean(4)),\n                clave, enTiempo(vencimiento())).stream().findFirst();\n    }\n\n    /**\n     * Reserva la clave. Devuelve false si otra petición la tiene en curso o ya terminó.\n     * Si la reserva existente nunca se completó y su concesión venció, la retoma.\n     */\n    boolean reservar(String clave, String huella) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE creado_utc <= ?\", enTiempo(vencimiento()));\n        try {\n            jdbc.update(\"INSERT INTO idempotencia (clave, huella, estatus_http, cuerpo, completada, creado_utc) VALUES (?, ?, 0, NULL, FALSE, ?)\",\n                    clave, huella, enTiempo(reloj.instant()));\n            return true;\n        } catch (DuplicateKeyException e) {\n            return retomarReservaVencida(clave, huella);\n        }\n    }\n\n    /** Solo una petición gana la retoma: el UPDATE es condicional, así que es atómico. */\n    private boolean retomarReservaVencida(String clave, String huella) {\n        Instant ahora = reloj.instant();\n        int filas = jdbc.update(\n                \"UPDATE idempotencia SET huella = ?, creado_utc = ? WHERE clave = ? AND completada = FALSE AND creado_utc <= ?\",\n                huella, enTiempo(ahora), clave, enTiempo(ahora.minus(CONCESION_RESERVA)));\n        return filas == 1;\n    }\n\n    /** Guarda la respuesta de una operación terminada. */\n    void completar(String clave, int estatus, String cuerpo) {\n        jdbc.update(\"UPDATE idempotencia SET estatus_http = ?, cuerpo = ?, completada = TRUE WHERE clave = ?\",\n                estatus, cuerpo, clave);\n    }\n\n    /** Libera la reserva cuando la operación falló, para que el cliente pueda reintentar. */\n    void liberar(String clave) {\n        jdbc.update(\"DELETE FROM idempotencia WHERE clave = ? AND completada = FALSE\", clave);\n    }\n\n    /** Calcula el límite de vigencia de las claves. */\n    private Instant vencimiento() {\n        return reloj.instant().minus(VIGENCIA);\n    }\n\n    /** Convierte un instante a Timestamp para la base de datos. */\n    private static Timestamp enTiempo(Instant instante) {\n        return Timestamp.from(instante);\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/indicadores/PublicadorIndicadoresOrdenes.java": "package com.mx.josesaid.develop.compras.infrastructure.indicadores;\n\nimport java.math.BigDecimal;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.concurrent.TimeUnit;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Publica a reportes-ejecutivos-ms dos indicadores mensuales del área de compras:\n * <ul>\n *   <li>{@code ordenes_mes}: órdenes creadas en el mes, en cualquier estatus (incluidas canceladas).<\/li>\n *   <li>{@code ordenes_canceladas_mes}: de esas, las que están en estatus CANCELADA.<\/li>\n * <\/ul>\n * Las órdenes anteriores a V3 reciben, en la migración V4, la fecha en que se aplicó esa migración.\n * Se recalculan el mes actual y el anterior en cada ciclo. Son fotos del periodo, no eventos: no pasan\n * por el outbox; si un envío falla, el siguiente ciclo lo corrige.\n */\n@Component\npublic class PublicadorIndicadoresOrdenes {\n\n    private static final Logger log = LoggerFactory.getLogger(PublicadorIndicadoresOrdenes.class);\n\n    /** Valor del enum Area de reportes-ejecutivos-ms. */\n    public static final String AREA = \"COMPRAS_PROVEEDORES\";\n    public static final String NOMBRE = \"ordenes_mes\";\n    public static final String NOMBRE_CANCELADAS = \"ordenes_canceladas_mes\";\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    private static final String SQL_ORDENES = \"\"\"\n            SELECT COUNT(*)::numeric\n            FROM ordenes_compra\n            WHERE creado_utc IS NOT NULL\n              AND TO_CHAR(creado_utc AT TIME ZONE 'America/Mexico_City', 'YYYY-MM') = ?\n            \"\"\";\n\n    private static final String SQL_CANCELADAS = \"\"\"\n            SELECT COUNT(*)::numeric\n            FROM ordenes_compra\n            WHERE creado_utc IS NOT NULL\n              AND estatus = 'CANCELADA'\n              AND TO_CHAR(creado_utc AT TIME ZONE 'America/Mexico_City', 'YYYY-MM') = ?\n            \"\"\";\n\n    private final JdbcTemplate jdbc;\n    private final KafkaTemplate<String, String> kafka;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n    private final String topico;\n\n    /** Recibe JDBC para contar, Kafka para publicar, el serializador, el reloj y el tópico. */\n    public PublicadorIndicadoresOrdenes(JdbcTemplate jdbc, KafkaTemplate<String, String> kafka,\n                                        ObjectMapper mapper, Clock reloj,\n                                        @Value(\"${indicadores.topico:indicadores-areas}\") String topico) {\n        this.jdbc = jdbc;\n        this.kafka = kafka;\n        this.mapper = mapper;\n        this.reloj = reloj;\n        this.topico = topico;\n    }\n\n    /** Publica el número de órdenes creadas en el mes actual y en el anterior. */\n    @Scheduled(fixedDelayString = \"${indicadores.intervalo-ms:3600000}\",\n            initialDelayString = \"${indicadores.inicio-ms:30000}\")\n    public void publicar() {\n        YearMonth actual = YearMonth.now(reloj.withZone(ZONA));\n        publicarPeriodo(actual.minusMonths(1).toString());\n        publicarPeriodo(actual.toString());\n    }\n\n    /** Calcula y envía los dos indicadores de un mes (\"AAAA-MM\"). */\n    public void publicarPeriodo(String periodo) {\n        enviar(NOMBRE, periodo, jdbc.queryForObject(SQL_ORDENES, BigDecimal.class, periodo));\n        enviar(NOMBRE_CANCELADAS, periodo, jdbc.queryForObject(SQL_CANCELADAS, BigDecimal.class, periodo));\n    }\n\n    /** Un fallo se registra y se reintenta en el siguiente ciclo. */\n    private void enviar(String nombre, String periodo, BigDecimal valor) {\n        String payload = mapper.writeValueAsString(\n                new IndicadorEvento(AREA, nombre, periodo, valor, Instant.now(reloj)));\n        try {\n            kafka.send(topico, AREA + \"|\" + nombre + \"|\" + periodo, payload).get(10, TimeUnit.SECONDS);\n            log.info(\"Indicador publicado: {} {} {}\", AREA, nombre, periodo);\n        } catch (InterruptedException ie) {\n            Thread.currentThread().interrupt();\n        } catch (Exception ex) {\n            log.warn(\"No se pudo publicar el indicador {} {}: {}\", nombre, periodo, ex.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Formato que espera reportes-ejecutivos-ms (ListenerIndicadores.IndicadorEvento).\n     *\n     * @param area área de negocio a la que pertenece, de tipo {@code String}.\n     * @param nombre nombre descriptivo, de tipo {@code String}.\n     * @param periodo periodo de referencia (por ejemplo, año y mes), de tipo {@code String}.\n     * @param valor valor registrado, de tipo {@code BigDecimal}.\n     * @param fuenteActualizadaUtc fecha y hora (UTC) de la última actualización de la fuente, de tipo {@code Instant}.\n     */\n    public record IndicadorEvento(String area, String nombre, String periodo, BigDecimal valor,\n                                  Instant fuenteActualizadaUtc) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/outbox/OutboxEntity.java": "package com.mx.josesaid.develop.compras.infrastructure.outbox;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.time.Instant;\nimport java.util.UUID;\n\n/** Evento pendiente de publicar a Kafka. Se escribe en la misma transacción que el cambio de negocio. */\n@Entity\n@Table(name = \"outbox_eventos\")\npublic class OutboxEntity {\n\n    @Id\n    private UUID id;\n\n    @Column(nullable = false, length = 100)\n    private String tipo;\n\n    @Column(name = \"agregado_id\", nullable = false, length = 100)\n    private String agregadoId;\n\n    /** Sobre JSON completo: tipo, agregadoId y datos. */\n    @Column(nullable = false, columnDefinition = \"TEXT\")\n    private String payload;\n\n    @Column(name = \"creado_utc\", nullable = false)\n    private Instant creadoUtc;\n\n    @Column(name = \"publicado_utc\")\n    private Instant publicadoUtc;\n\n    @Column(nullable = false)\n    private int intentos;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OutboxEntity() {\n        // requerido por JPA\n    }\n\n    /** Crea un evento pendiente de publicar en el outbox. */\n    public OutboxEntity(UUID id, String tipo, String agregadoId, String payload, Instant creadoUtc) {\n        this.id = id;\n        this.tipo = tipo;\n        this.agregadoId = agregadoId;\n        this.payload = payload;\n        this.creadoUtc = creadoUtc;\n        this.intentos = 0;\n    }\n\n    /** Marca el evento como publicado en la fecha indicada. */\n    public void marcarPublicado(Instant ahora) {\n        this.publicadoUtc = ahora;\n    }\n\n    /** Suma un intento fallido de publicación. */\n    public void registrarIntentoFallido() {\n        this.intentos++;\n    }\n\n    /** Devuelve el identificador del evento. */\n    public UUID getId() { return id; }\n    /** Devuelve el tipo del evento. */\n    public String getTipo() { return tipo; }\n    /** Devuelve el id del agregado al que pertenece el evento. */\n    public String getAgregadoId() { return agregadoId; }\n    /** Devuelve el contenido JSON del evento. */\n    public String getPayload() { return payload; }\n    /** Devuelve la fecha de creación en UTC. */\n    public Instant getCreadoUtc() { return creadoUtc; }\n    /** Devuelve la fecha de publicación en UTC, o nula si no se ha publicado. */\n    public Instant getPublicadoUtc() { return publicadoUtc; }\n    /** Devuelve el número de intentos fallidos. */\n    public int getIntentos() { return intentos; }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/outbox/OutboxJpaRepository.java": "package com.mx.josesaid.develop.compras.infrastructure.outbox;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla del outbox con Spring Data JPA. */\npublic interface OutboxJpaRepository extends JpaRepository<OutboxEntity, UUID> {\n\n    /** Eventos pendientes, del más antiguo al más nuevo, en lotes de 100. */\n    List<OutboxEntity> findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc();\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/outbox/PublicadorEventosOutbox.java": "package com.mx.josesaid.develop.compras.infrastructure.outbox;\n\nimport com.mx.josesaid.develop.compras.application.EventoDominio;\nimport com.mx.josesaid.develop.compras.application.PublicadorEventos;\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Implementación del patrón outbox: guarda el evento en la base de datos dentro de la\n * transacción de negocio. El envío a Kafka lo hace {@link RetransmisorOutbox}.\n */\n@Component\npublic class PublicadorEventosOutbox implements PublicadorEventos {\n\n    private final OutboxJpaRepository outbox;\n    private final ObjectMapper mapper;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el serializador JSON y el reloj. */\n    public PublicadorEventosOutbox(OutboxJpaRepository outbox, ObjectMapper mapper, Clock reloj) {\n        this.outbox = outbox;\n        this.mapper = mapper;\n        this.reloj = reloj;\n    }\n\n    /** Guarda el evento en el outbox dentro de la misma transacción que el cambio de datos. */\n    @Override\n    public void publicar(EventoDominio evento) {\n        String sobre = mapper.writeValueAsString(Map.of(\n                \"tipo\", evento.tipo(),\n                \"agregadoId\", evento.agregadoId(),\n                \"datos\", evento.datos()));\n        outbox.save(new OutboxEntity(UUID.randomUUID(), evento.tipo(), evento.agregadoId(),\n                sobre, Instant.now(reloj)));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/outbox/RetransmisorOutbox.java": "package com.mx.josesaid.develop.compras.infrastructure.outbox;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.kafka.core.KafkaTemplate;\nimport org.springframework.scheduling.annotation.Scheduled;\nimport org.springframework.stereotype.Component;\nimport org.springframework.transaction.annotation.Transactional;\n\n/**\n * Envía a Kafka los eventos pendientes del outbox.\n *\n * <p>Se detiene en el primer fallo para conservar el orden de los eventos.\n * Un evento con error queda pendiente y se reintenta en el siguiente ciclo.\n */\n@Component\npublic class RetransmisorOutbox {\n\n    /** Tópico donde se publican los eventos de identidad. */\n    public static final String TOPICO = \"compras.eventos\";\n\n    private final OutboxJpaRepository outbox;\n    private final KafkaTemplate<String, String> kafka;\n    private final Clock reloj;\n\n    /** Recibe el repositorio del outbox, el productor de Kafka y el reloj. */\n    public RetransmisorOutbox(OutboxJpaRepository outbox, KafkaTemplate<String, String> kafka, Clock reloj) {\n        this.outbox = outbox;\n        this.kafka = kafka;\n        this.reloj = reloj;\n    }\n\n    /** Envía a Kafka los eventos pendientes. Si el envío falla, el evento queda para el siguiente intento. */\n    @Scheduled(fixedDelayString = \"${compras.outbox.intervalo-ms:5000}\")\n    @Transactional\n    public void transmitir() {\n        for (OutboxEntity evento : outbox.findTop100ByPublicadoUtcIsNullOrderByCreadoUtcAsc()) {\n            try {\n                kafka.send(TOPICO, evento.getAgregadoId(), evento.getPayload()).get(10, TimeUnit.SECONDS);\n                evento.marcarPublicado(Instant.now(reloj));\n            } catch (InterruptedException ie) {\n                Thread.currentThread().interrupt();\n                return;\n            } catch (Exception ex) {\n                evento.registrarIntentoFallido();\n                return;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/LineaOrdenEntity.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.JoinColumn;\nimport jakarta.persistence.ManyToOne;\nimport jakarta.persistence.Table;\nimport java.math.BigDecimal;\nimport java.util.UUID;\n\n/** Fila de una línea de orden de compra, embebida en la orden. */\n@Entity\n@Table(name = \"lineas_orden\")\nclass LineaOrdenEntity {\n    @Id UUID id;\n    @ManyToOne(fetch = FetchType.LAZY, optional = false) @JoinColumn(name = \"orden_id\", nullable = false) OrdenCompraEntity orden;\n    @Column(name = \"articulo_sku\", nullable = false, length = 40) String articuloSku;\n    @Column(name = \"cantidad_ordenada\", nullable = false, precision = 14, scale = 3) BigDecimal cantidadOrdenada;\n    @Column(name = \"cantidad_recibida\", nullable = false, precision = 14, scale = 3) BigDecimal cantidadRecibida;\n    @Column(name = \"precio_unitario\", nullable = false, precision = 14, scale = 2) BigDecimal precioUnitario;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected LineaOrdenEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/OrdenCompraEntity.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.compras.domain.EstatusOrdenCompra;\nimport jakarta.persistence.CascadeType;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.FetchType;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.OneToMany;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.util.ArrayList;\nimport java.util.List;\nimport java.util.UUID;\n\n/** Fila de la tabla de órdenes de compra, con sus líneas. */\n@Entity\n@Table(name = \"ordenes_compra\")\nclass OrdenCompraEntity {\n    @Id UUID id;\n    @Column(name = \"proveedor_id\", nullable = false) UUID proveedorId;\n    @Column(nullable = false, length = 3) String moneda;\n    @Enumerated(EnumType.STRING) @Column(nullable = false, length = 20) EstatusOrdenCompra estatus;\n    @Column(name = \"motivo_cancelacion\", length = 200) String motivoCancelacion;\n    @Column(name = \"creada_por\", length = 255) String creadaPor;\n    @Column(name = \"creado_utc\", insertable = false, updatable = false) java.time.Instant creadoUtc;\n    @Version Long version;\n    @OneToMany(mappedBy = \"orden\", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.EAGER)\n    List<LineaOrdenEntity> lineas = new ArrayList<>();\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected OrdenCompraEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/OrdenCompraJpaRepository.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.domain.Pageable;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de órdenes de compra con Spring Data JPA. */\ninterface OrdenCompraJpaRepository extends JpaRepository<OrdenCompraEntity, UUID> {\n\n    List<OrdenCompraEntity> findAllByOrderByCreadoUtcDesc(Pageable pagina);\n\n    List<OrdenCompraEntity> findByEstatusOrderByCreadoUtcDesc(com.mx.josesaid.develop.compras.domain.EstatusOrdenCompra estatus, Pageable pagina);\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/OrdenCompraRepositorioJpa.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.compras.domain.LineaOrden;\nimport com.mx.josesaid.develop.compras.domain.OrdenCompra;\nimport com.mx.josesaid.develop.compras.domain.OrdenCompraRepositorio;\nimport com.mx.josesaid.develop.compras.domain.EstatusOrdenCompra;\nimport com.mx.josesaid.develop.compras.domain.ResumenOrdenCompra;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.data.domain.PageRequest;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de órdenes de compra con JPA. */\n@Component\nclass OrdenCompraRepositorioJpa implements OrdenCompraRepositorio {\n\n    private final OrdenCompraJpaRepository jpa;\n\n    OrdenCompraRepositorioJpa(OrdenCompraJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Una orden nueva guarda sus líneas. Una existente actualiza estatus y cantidades recibidas. */\n    @Override\n    public OrdenCompra guardar(OrdenCompra o) {\n        Optional<OrdenCompraEntity> existente = jpa.findById(o.getId());\n        OrdenCompraEntity e;\n        if (existente.isEmpty()) {\n            e = new OrdenCompraEntity();\n            e.id = o.getId();\n            e.proveedorId = o.getProveedorId();\n            e.moneda = o.getMoneda();\n            e.creadaPor = o.getCreadaPor();\n            for (LineaOrden l : o.getLineas()) {\n                LineaOrdenEntity le = new LineaOrdenEntity();\n                le.id = UUID.randomUUID();\n                le.orden = e;\n                le.articuloSku = l.getArticuloSku();\n                le.cantidadOrdenada = l.getCantidadOrdenada();\n                le.cantidadRecibida = l.getCantidadRecibida();\n                le.precioUnitario = l.getPrecioUnitario();\n                e.lineas.add(le);\n            }\n        } else {\n            e = existente.get();\n            for (LineaOrdenEntity le : e.lineas) {\n                o.getLineas().stream()\n                        .filter(l -> l.getArticuloSku().equals(le.articuloSku))\n                        .findFirst()\n                        .ifPresent(l -> le.cantidadRecibida = l.getCantidadRecibida());\n            }\n        }\n        e.estatus = o.getEstatus();\n        e.motivoCancelacion = o.getMotivoCancelacion();\n        jpa.save(e);\n        return o;\n    }\n\n    /** Busca una orden por id. */\n    @Override\n    public Optional<OrdenCompra> buscarPorId(UUID id) {\n        return jpa.findById(id).map(e -> {\n            List<LineaOrden> lineas = e.lineas.stream()\n                    .map(le -> LineaOrden.reconstruir(le.articuloSku, le.cantidadOrdenada, le.cantidadRecibida,\n                            le.precioUnitario))\n                    .toList();\n            return OrdenCompra.reconstruir(e.id, e.proveedorId, e.moneda, e.estatus, e.motivoCancelacion, lineas,\n                    e.creadaPor);\n        });\n    }\n\n    /** Lista las órdenes más recientes, opcionalmente filtradas por estatus, con límite. */\n    @Override\n    public List<ResumenOrdenCompra> listarRecientes(EstatusOrdenCompra estatus, int limite) {\n        var pagina = PageRequest.of(0, limite);\n        List<OrdenCompraEntity> filas = estatus == null\n                ? jpa.findAllByOrderByCreadoUtcDesc(pagina)\n                : jpa.findByEstatusOrderByCreadoUtcDesc(estatus, pagina);\n        return filas.stream()\n                .map(e -> new ResumenOrdenCompra(e.id, e.proveedorId, e.estatus, e.creadoUtc))\n                .toList();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/ProveedorEntity.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.compras.domain.EstatusProveedor;\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.EnumType;\nimport jakarta.persistence.Enumerated;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport jakarta.persistence.Version;\nimport java.util.UUID;\n\n/** Fila de la tabla de proveedores. */\n@Entity\n@Table(name = \"proveedores\")\nclass ProveedorEntity {\n    @Id UUID id;\n    @Column(name = \"razon_social\", nullable = false, length = 200) String razonSocial;\n    @Column(name = \"rfc_cifrado\", nullable = false, columnDefinition = \"TEXT\") String rfcCifrado;\n    @Column(name = \"rfc_indice\", nullable = false, unique = true, length = 64) String rfcIndice;\n    @Column(name = \"correo_cifrado\", nullable = false, columnDefinition = \"TEXT\") String correoCifrado;\n    @Enumerated(EnumType.STRING) @Column(nullable = false, length = 12) EstatusProveedor estatus;\n    @Version Long version;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected ProveedorEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/ProveedorJpaRepository.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport java.util.List;\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de proveedores con Spring Data JPA. */\ninterface ProveedorJpaRepository extends JpaRepository<ProveedorEntity, UUID> {\n    boolean existsByRfcIndice(String rfcIndice);\n\n    List<ProveedorEntity> findTop20ByRazonSocialContainingIgnoreCaseOrderByRazonSocialAsc(String texto);\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/ProveedorRepositorioJpa.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.compras.domain.Proveedor;\nimport com.mx.josesaid.develop.compras.domain.ProveedorRepositorio;\nimport com.mx.josesaid.develop.compras.infrastructure.seguridad.ProtectorDatos;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de proveedores con JPA. */\n@Component\nclass ProveedorRepositorioJpa implements ProveedorRepositorio {\n\n    private final ProveedorJpaRepository jpa;\n    private final ProtectorDatos protector;\n\n    ProveedorRepositorioJpa(ProveedorJpaRepository jpa, ProtectorDatos protector) {\n        this.jpa = jpa;\n        this.protector = protector;\n    }\n\n    /** Guarda un proveedor y devuelve el guardado. */\n    @Override\n    public Proveedor guardar(Proveedor p) {\n        ProveedorEntity e = jpa.findById(p.getId()).orElseGet(() -> {\n            ProveedorEntity nueva = new ProveedorEntity();\n            nueva.id = p.getId();\n            return nueva;\n        });\n        e.razonSocial = p.getRazonSocial();\n        e.rfcCifrado = protector.cifrar(p.getRfc());\n        e.rfcIndice = protector.indice(p.getRfc());\n        e.correoCifrado = protector.cifrar(p.getCorreo());\n        e.estatus = p.getEstatus();\n        jpa.save(e);\n        return p;\n    }\n\n    /** Busca un proveedor por id. */\n    @Override\n    public Optional<Proveedor> buscarPorId(UUID id) {\n        return jpa.findById(id).map(e -> Proveedor.reconstruir(e.id, e.razonSocial,\n                protector.descifrar(e.rfcCifrado), protector.descifrar(e.correoCifrado), e.estatus));\n    }\n\n    /** Indica si ya existe un proveedor con ese RFC. */\n    @Override\n    public boolean existePorRfc(String rfc) {\n        return jpa.existsByRfcIndice(protector.indice(rfc));\n    }\n\n    /** Busca proveedores cuya razón social contiene el texto indicado. */\n    @Override\n    public List<Proveedor> buscarPorRazonSocial(String texto) {\n        return jpa.findTop20ByRazonSocialContainingIgnoreCaseOrderByRazonSocialAsc(texto).stream()\n                .map(e -> Proveedor.reconstruir(e.id, e.razonSocial,\n                        protector.descifrar(e.rfcCifrado), protector.descifrar(e.correoCifrado), e.estatus))\n                .toList();\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/RecepcionEntity.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport jakarta.persistence.Column;\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.Id;\nimport jakarta.persistence.Table;\nimport java.math.BigDecimal;\nimport java.time.LocalDate;\nimport java.util.UUID;\n\n/** Fila de la tabla de recepciones de mercancía. */\n@Entity\n@Table(name = \"recepciones\")\nclass RecepcionEntity {\n    @Id UUID id;\n    @Column(name = \"orden_id\", nullable = false) UUID ordenId;\n    @Column(name = \"articulo_sku\", nullable = false, length = 40) String articuloSku;\n    @Column(nullable = false, precision = 14, scale = 3) BigDecimal cantidad;\n    @Column(nullable = false) LocalDate fecha;\n\n    /** Constructor exigido por JPA. No se usa en el código de la aplicación. */\n    protected RecepcionEntity() {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/RecepcionJpaRepository.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport java.util.UUID;\nimport org.springframework.data.jpa.repository.JpaRepository;\n\n/** Acceso a la tabla de recepciones con Spring Data JPA. */\ninterface RecepcionJpaRepository extends JpaRepository<RecepcionEntity, UUID> {\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/persistence/RecepcionRepositorioJpa.java": "package com.mx.josesaid.develop.compras.infrastructure.persistence;\n\nimport com.mx.josesaid.develop.compras.domain.Recepcion;\nimport com.mx.josesaid.develop.compras.domain.RecepcionRepositorio;\nimport java.time.LocalDate;\nimport java.time.ZoneId;\nimport org.springframework.stereotype.Component;\n\n/** Implementa el puerto de recepciones con JPA. */\n@Component\nclass RecepcionRepositorioJpa implements RecepcionRepositorio {\n\n    private final RecepcionJpaRepository jpa;\n\n    RecepcionRepositorioJpa(RecepcionJpaRepository jpa) {\n        this.jpa = jpa;\n    }\n\n    /** Guarda una recepción y devuelve la guardada. */\n    @Override\n    public Recepcion guardar(Recepcion r) {\n        RecepcionEntity e = new RecepcionEntity();\n        e.id = r.id();\n        e.ordenId = r.ordenId();\n        e.articuloSku = r.articuloSku();\n        e.cantidad = r.cantidad();\n        e.fecha = LocalDate.now(ZoneId.of(\"America/Mexico_City\"));\n        jpa.save(e);\n        return r;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/seguridad/ProtectorDatos.java": "package com.mx.josesaid.develop.compras.infrastructure.seguridad;\n\nimport java.nio.ByteBuffer;\nimport java.nio.charset.StandardCharsets;\nimport java.security.GeneralSecurityException;\nimport java.security.SecureRandom;\nimport java.util.Arrays;\nimport java.util.Base64;\nimport java.util.HashMap;\nimport java.util.Map;\nimport java.util.regex.Matcher;\nimport java.util.regex.Pattern;\nimport javax.crypto.Cipher;\nimport javax.crypto.Mac;\nimport javax.crypto.spec.GCMParameterSpec;\nimport javax.crypto.spec.SecretKeySpec;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.beans.factory.annotation.Value;\nimport org.springframework.stereotype.Component;\n\n/**\n * Cifra datos sensibles con AES-256-GCM y genera un índice HMAC-SHA256 para buscar sin descifrar.\n * <p>\n * Formato en la columna: {@code v<N>:Base64(IV || cifrado+tag)}, donde N es la versión de la clave con la\n * que se cifró. Los valores sin prefijo son de la versión 1 y se siguen leyendo.\n * Las claves vienen de variables de entorno; sin ellas el servicio no arranca.\n */\n@Component\npublic class ProtectorDatos {\n\n    private static final int TAMANO_IV = 12;\n    private static final int TAMANO_TAG_BITS = 128;\n    private static final int VERSION_UNICA = 1;\n    private static final Pattern PREFIJO_VERSION = Pattern.compile(\"^v(\\\\d{1,4}):(.*)$\", Pattern.DOTALL);\n\n    private final Map<Integer, SecretKeySpec> clavesCifrado;\n    private final int versionActiva;\n    private final SecretKeySpec claveIndice;\n    private final SecureRandom aleatorio = new SecureRandom();\n\n    /** Una sola clave de cifrado, como versión 1. Se usa en pruebas y como constructor simple. */\n    public ProtectorDatos(String claveCifradoBase64, String claveIndiceBase64) {\n        this(claveCifradoBase64, \"\", VERSION_UNICA, claveIndiceBase64);\n    }\n\n    /** Carga las claves de cifrado y de índice desde la configuración. Falla al arrancar si la versión activa no existe o la clave de índice tiene menos de 32 bytes. */\n    @Autowired\n    public ProtectorDatos(@Value(\"${compras.cifrado.clave:}\") String claveCifradoBase64,\n                          @Value(\"${compras.cifrado.claves:}\") String clavesCifradoBase64,\n                          @Value(\"${compras.cifrado.version-activa:1}\") int versionActiva,\n                          @Value(\"${compras.cifrado.indice-clave:}\") String claveIndiceBase64) {\n        this.clavesCifrado = cargarClavesCifrado(claveCifradoBase64, clavesCifradoBase64);\n        if (!clavesCifrado.containsKey(versionActiva)) {\n            throw new IllegalStateException(\"La versión activa de clave de cifrado \" + versionActiva + \" no está configurada\");\n        }\n        this.versionActiva = versionActiva;\n        byte[] indice = decodificar(claveIndiceBase64);\n        if (indice.length < 32) {\n            throw new IllegalStateException(\"compras.cifrado.indice-clave debe tener al menos 32 bytes en base64\");\n        }\n        this.claveIndice = new SecretKeySpec(indice, \"HmacSHA256\");\n    }\n\n    /** Construye el mapa de claves AES por versión a partir de la clave única y la lista configurada. */\n    private static Map<Integer, SecretKeySpec> cargarClavesCifrado(String claveUnica, String lista) {\n        Map<Integer, SecretKeySpec> claves = new HashMap<>();\n        if (lista != null && !lista.isBlank()) {\n            for (String entrada : lista.split(\",\")) {\n                String[] partes = entrada.trim().split(\":\", 2);\n                if (partes.length != 2) {\n                    throw new IllegalStateException(\"compras.cifrado.claves debe tener el formato N:base64,N:base64\");\n                }\n                int numero = Integer.parseInt(partes[0].trim());\n                if (claves.put(numero, claveAes(decodificar(partes[1]))) != null) {\n                    throw new IllegalStateException(\"La versión \" + numero + \" de clave aparece más de una vez\");\n                }\n            }\n        } else {\n            claves.put(VERSION_UNICA, claveAes(decodificar(claveUnica)));\n        }\n        return claves;\n    }\n\n    /** Crea una clave AES a partir de sus bytes. */\n    private static SecretKeySpec claveAes(byte[] bytes) {\n        if (bytes.length != 32) {\n            throw new IllegalStateException(\"La clave de cifrado debe ser AES-256 de 32 bytes en base64\");\n        }\n        return new SecretKeySpec(bytes, \"AES\");\n    }\n\n    /** Decodifica un valor en Base64. Un valor vacío devuelve un arreglo vacío. */\n    private static byte[] decodificar(String base64) {\n        if (base64 == null || base64.isBlank()) {\n            return new byte[0];\n        }\n        return Base64.getDecoder().decode(base64.trim());\n    }\n\n    /** Cifra un texto con AES-256-GCM y un IV aleatorio. Devuelve el valor con el prefijo de versión. */\n    public String cifrar(String claro) {\n        try {\n            byte[] iv = new byte[TAMANO_IV];\n            aleatorio.nextBytes(iv);\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.ENCRYPT_MODE, clavesCifrado.get(versionActiva), new GCMParameterSpec(TAMANO_TAG_BITS, iv));\n            byte[] cifrado = cipher.doFinal(claro.getBytes(StandardCharsets.UTF_8));\n            byte[] salida = ByteBuffer.allocate(iv.length + cifrado.length).put(iv).put(cifrado).array();\n            return \"v\" + versionActiva + \":\" + Base64.getEncoder().encodeToString(salida);\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo cifrar el dato\", e);\n        }\n    }\n\n    /** Descifra un valor usando la versión de clave indicada en su prefijo. Falla si esa versión no está configurada. */\n    public String descifrar(String cifradoBase64) {\n        int version = VERSION_UNICA;\n        String cuerpo = cifradoBase64;\n        Matcher prefijo = PREFIJO_VERSION.matcher(cifradoBase64);\n        if (prefijo.matches()) {\n            version = Integer.parseInt(prefijo.group(1));\n            cuerpo = prefijo.group(2);\n        }\n        SecretKeySpec clave = clavesCifrado.get(version);\n        if (clave == null) {\n            throw new IllegalStateException(\"Versión de clave de cifrado no configurada: \" + version);\n        }\n        try {\n            byte[] entrada = Base64.getDecoder().decode(cuerpo);\n            byte[] iv = Arrays.copyOfRange(entrada, 0, TAMANO_IV);\n            byte[] contenido = Arrays.copyOfRange(entrada, TAMANO_IV, entrada.length);\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.DECRYPT_MODE, clave, new GCMParameterSpec(TAMANO_TAG_BITS, iv));\n            return new String(cipher.doFinal(contenido), StandardCharsets.UTF_8);\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo descifrar el dato\", e);\n        }\n    }\n\n    /** Versión con la que se cifra lo nuevo. */\n    public int versionActiva() {\n        return versionActiva;\n    }\n\n    /** Índice determinista para búsquedas por igualdad, por ejemplo el RFC. */\n    public String indice(String valor) {\n        try {\n            Mac mac = Mac.getInstance(\"HmacSHA256\");\n            mac.init(claveIndice);\n            return Base64.getEncoder().encodeToString(mac.doFinal(valor.getBytes(StandardCharsets.UTF_8)));\n        } catch (GeneralSecurityException e) {\n            throw new IllegalStateException(\"No se pudo generar el índice\", e);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/seguridad/RecifradorCamposRunner.java": "package com.mx.josesaid.develop.compras.infrastructure.seguridad;\n\nimport java.util.List;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;\nimport org.springframework.stereotype.Component;\n\n/**\n * Re-cifra los datos sensibles de proveedores a la versión activa. Solo corre con\n * {@code COMPRAS_RECIFRADO_ACTIVO=true}; por defecto no toca datos. Registra solo conteos, nunca valores.\n * El índice {@code rfc_indice} no cambia, así que no hace falta recalcularlo.\n */\n@Component\n@ConditionalOnProperty(name = \"COMPRAS_RECIFRADO_ACTIVO\", havingValue = \"true\")\npublic class RecifradorCamposRunner implements ApplicationRunner {\n\n    private static final Logger log = LoggerFactory.getLogger(RecifradorCamposRunner.class);\n    private static final int TAMANO_LOTE = 500;\n    /** Columnas sensibles que se re-cifran a la versión activa de la clave. */\n    private static final List<String[]> CAMPOS = List.of(\n            new String[] {\"proveedores\", \"rfc_cifrado\"},\n            new String[] {\"proveedores\", \"correo_cifrado\"});\n\n    private final RecifradorJdbc almacen;\n    private final ProtectorDatos protector;\n\n    /** Recibe el acceso JDBC a las columnas y el protector de datos. */\n    public RecifradorCamposRunner(RecifradorJdbc almacen, ProtectorDatos protector) {\n        this.almacen = almacen;\n        this.protector = protector;\n    }\n\n    /** Al arrancar, re-cifra las columnas de la lista a la versión activa. */\n    @Override\n    public void run(ApplicationArguments args) {\n        RecifradorPorLotes recifrador = new RecifradorPorLotes(almacen, TAMANO_LOTE,\n                valor -> protector.cifrar(protector.descifrar(valor)));\n        for (String[] campo : CAMPOS) {\n            int total = recifrador.ejecutar(campo[0], campo[1]);\n            log.info(\"Campos re-cifrados en {}.{}: {}\", campo[0], campo[1], total);\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/seguridad/RecifradorJdbc.java": "package com.mx.josesaid.develop.compras.infrastructure.seguridad;\n\nimport java.util.List;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.stereotype.Component;\n\n/**\n * Implementación JDBC de {@link RecifradorPorLotes.Almacen}. Tabla y columna vienen de constantes del código\n * (nunca de entrada del usuario), así que se componen en el SQL; los valores van como parámetros.\n */\n@Component\npublic class RecifradorJdbc implements RecifradorPorLotes.Almacen {\n\n    private final JdbcTemplate jdbc;\n    private final ProtectorDatos protector;\n\n    /** Recibe JDBC para leer y actualizar, y el protector de datos. */\n    public RecifradorJdbc(JdbcTemplate jdbc, ProtectorDatos protector) {\n        this.jdbc = jdbc;\n        this.protector = protector;\n    }\n\n    /** Devuelve hasta el límite de filas cuyo valor aún no está en la versión activa. */\n    @Override\n    public List<RecifradorPorLotes.Fila> pendientes(String tabla, String columna, int limite) {\n        String sql = \"SELECT id, \" + columna + \" AS valor FROM \" + tabla\n                + \" WHERE \" + columna + \" IS NOT NULL AND \" + columna + \" NOT LIKE ? ORDER BY id LIMIT ?\";\n        return jdbc.query(sql,\n                (resultado, fila) -> new RecifradorPorLotes.Fila(resultado.getObject(\"id\"), resultado.getString(\"valor\")),\n                \"v\" + protector.versionActiva() + \":%\",\n                limite);\n    }\n\n    /** Cambia el valor de una fila solo si aún vale lo que se leyó. */\n    @Override\n    public boolean actualizar(String tabla, String columna, Object id, String valorAnterior, String valorNuevo) {\n        String sql = \"UPDATE \" + tabla + \" SET \" + columna + \" = ? WHERE id = ? AND \" + columna + \" = ?\";\n        return jdbc.update(sql, valorNuevo, id, valorAnterior) == 1;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/infrastructure/seguridad/RecifradorPorLotes.java": "package com.mx.josesaid.develop.compras.infrastructure.seguridad;\n\nimport java.util.List;\nimport java.util.function.UnaryOperator;\n\n/**\n * Vuelve a cifrar, por lotes, los valores de una columna que no están en la versión activa de la clave.\n * <p>\n * Es reanudable: solo pide filas pendientes, así que si el proceso se corta, al volver a correrlo continúa\n * donde quedó. Cada fila se actualiza solo si su valor sigue siendo el que se leyó, para no pisar una escritura\n * concurrente de la aplicación.\n */\npublic final class RecifradorPorLotes {\n\n    /**\n     * Fila pendiente: su id y el valor cifrado tal como está en la base.\n     *\n     * @param id identificador único del registro, de tipo {@code Object}.\n     * @param valor valor registrado, de tipo {@code String}.\n     */\n    public record Fila(Object id, String valor) {\n    }\n\n    /** Acceso a la base; la implementación JDBC vive aparte para poder probar la lógica sin base de datos. */\n    public interface Almacen {\n\n        /** Hasta {@code limite} filas con valor no nulo que no están en la versión activa. */\n        List<Fila> pendientes(String tabla, String columna, int limite);\n\n        /** Cambia el valor solo si la columna aún vale {@code valorAnterior}. Devuelve si se cambió. */\n        boolean actualizar(String tabla, String columna, Object id, String valorAnterior, String valorNuevo);\n    }\n\n    private final Almacen almacen;\n    private final int tamanoLote;\n    private final UnaryOperator<String> recifrar;\n\n    /** Recibe el acceso a la base, el tamaño de lote y la función que re-cifra un valor. */\n    public RecifradorPorLotes(Almacen almacen, int tamanoLote, UnaryOperator<String> recifrar) {\n        if (tamanoLote < 1) {\n            throw new IllegalArgumentException(\"El tamaño de lote debe ser al menos 1\");\n        }\n        this.almacen = almacen;\n        this.tamanoLote = tamanoLote;\n        this.recifrar = recifrar;\n    }\n\n    /** Recorre la columna hasta que no queden filas pendientes. Devuelve cuántas se re-cifraron. */\n    public int ejecutar(String tabla, String columna) {\n        int recifradas = 0;\n        while (true) {\n            List<Fila> lote = almacen.pendientes(tabla, columna, tamanoLote);\n            if (lote.isEmpty()) {\n                return recifradas;\n            }\n            for (Fila fila : lote) {\n                String nuevo = recifrar.apply(fila.valor());\n                if (!almacen.actualizar(tabla, columna, fila.id(), fila.valor(), nuevo)) {\n                    throw new IllegalStateException(\n                            \"No se actualizó \" + tabla + \".\" + columna + \" para el id \" + fila.id()\n                                    + \": el valor cambió durante el proceso. Vuelva a ejecutar.\");\n                }\n                recifradas++;\n            }\n        }\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/seguridad/EntradaNoAutorizada.java": "package com.mx.josesaid.develop.compras.seguridad;\n\nimport jakarta.servlet.http.HttpServletRequest;\nimport jakarta.servlet.http.HttpServletResponse;\nimport java.io.IOException;\nimport org.springframework.security.core.AuthenticationException;\nimport org.springframework.security.oauth2.jwt.JwtValidationException;\nimport org.springframework.security.web.AuthenticationEntryPoint;\n\n/**\n * Responde 401 y deja el motivo en WWW-Authenticate. Solo expone el motivo de sesión cerrada;\n * cualquier otro fallo de validación se reporta como \"Invalid token\", sin detalles de decodificación.\n * Spring puede llamar dos veces al punto de entrada en la misma petición: el primer motivo se conserva.\n */\npublic class EntradaNoAutorizada implements AuthenticationEntryPoint {\n\n    private static final String MOTIVO_GENERICO = \"Invalid token\";\n    private static final String ATRIBUTO = EntradaNoAutorizada.class.getName() + \".motivo\";\n\n    /** Responde 401 cuando la petición no trae un token válido o el token fue rechazado. */\n    @Override\n    public void commence(HttpServletRequest request, HttpServletResponse response, AuthenticationException ex)\n            throws IOException {\n        String previo = (String) request.getAttribute(ATRIBUTO);\n        String motivo = previo != null ? previo : motivo(ex);\n        request.setAttribute(ATRIBUTO, motivo);\n        response.setHeader(\"WWW-Authenticate\",\n                \"Bearer error=\\\"invalid_token\\\", error_description=\\\"\" + motivo + \"\\\"\");\n        response.sendError(HttpServletResponse.SC_UNAUTHORIZED);\n    }\n\n    /** Explica por qué se rechazó el token, en texto breve para el log. */\n    private static String motivo(Throwable ex) {\n        for (Throwable t = ex; t != null; t = t.getCause()) {\n            if (t instanceof JwtValidationException jve && jve.getErrors().stream()\n                    .anyMatch(e -> ValidadorRevocacion.MOTIVO.equals(e.getDescription()))) {\n                return ValidadorRevocacion.MOTIVO;\n            }\n        }\n        return MOTIVO_GENERICO;\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/seguridad/ListenerRevocaciones.java": "package com.mx.josesaid.develop.compras.seguridad;\n\nimport java.time.Instant;\nimport java.util.Map;\nimport org.slf4j.Logger;\nimport org.slf4j.LoggerFactory;\nimport org.springframework.kafka.annotation.KafkaListener;\nimport org.springframework.stereotype.Component;\nimport tools.jackson.databind.ObjectMapper;\n\n/**\n * Recibe de usuarios-accesos-ms los cierres de sesión y los aplica a la copia local de revocaciones.\n * Los eventos ajenos se ignoran; un mensaje inválido se registra y se descarta.\n * Cada arranque usa un grupo de consumo nuevo y lee el topic desde el inicio: así reconstruye las\n * revocaciones vigentes. Los eventos vencidos los descarta RevocacionSesiones.\n */\n@Component\npublic class ListenerRevocaciones {\n\n    private static final Logger log = LoggerFactory.getLogger(ListenerRevocaciones.class);\n\n    private final RevocacionSesiones revocaciones;\n    private final ObjectMapper mapper;\n\n    /** Recibe la copia local de revocaciones y el lector JSON. */\n    public ListenerRevocaciones(RevocacionSesiones revocaciones, ObjectMapper mapper) {\n        this.revocaciones = revocaciones;\n        this.mapper = mapper;\n    }\n\n    /** Aplica al instante un evento de cierre de sesión recibido por Kafka. */\n    @KafkaListener(topics = \"${seguridad.revocaciones.topico:usuarios-accesos.eventos}\",\n                   groupId = \"compras-proveedores-ms-revocaciones-#{T(java.util.UUID).randomUUID()}\",\n                   properties = \"auto.offset.reset=earliest\")\n    public void recibir(String mensaje) {\n        try {\n            Sobre sobre = mapper.readValue(mensaje, Sobre.class);\n            String tipo = sobre.tipo();\n            if (!\"sesion-cerrada\".equals(tipo) && !\"sesiones-usuario-cerradas\".equals(tipo)) {\n                return;\n            }\n            Map<String, Object> datos = sobre.datos() == null ? Map.of() : sobre.datos();\n            Instant ocurridoEn = Instant.parse(String.valueOf(datos.get(\"ocurridoEn\")));\n            if (\"sesion-cerrada\".equals(tipo)) {\n                revocaciones.revocarSesion(String.valueOf(datos.get(\"sid\")), ocurridoEn);\n            } else {\n                revocaciones.revocarUsuario(String.valueOf(datos.get(\"usuarioId\")), ocurridoEn);\n            }\n        } catch (RuntimeException e) {\n            log.warn(\"Evento de revocación descartado: {}\", e.getClass().getSimpleName());\n        }\n    }\n\n    /**\n     * Sobre que publica usuarios-accesos-ms por el outbox.\n     *\n     * @param tipo tipo o clasificación del registro, de tipo {@code String}.\n     * @param agregadoId identificador del agregado de dominio al que pertenece el evento, de tipo {@code String}.\n     * @param datos datos específicos de la operación, de tipo {@code Map<String, Object>}.\n     */\n    public record Sobre(String tipo, String agregadoId, Map<String, Object> datos) {\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/seguridad/RevocacionSesiones.java": "package com.mx.josesaid.develop.compras.seguridad;\n\nimport java.time.Duration;\nimport java.time.Instant;\nimport java.util.Map;\nimport java.util.concurrent.ConcurrentHashMap;\nimport org.springframework.stereotype.Component;\n\n/**\n * Sesiones cerradas, recordadas en memoria solo mientras pueda haber tokens vigentes.\n * Cada servicio mantiene su copia: un reinicio la vacía, y los tokens revocados expiran igual en 15 minutos.\n */\n@Component\npublic class RevocacionSesiones {\n\n    /** Vida del access token (15 min) más un margen. Pasado ese tiempo, ningún token revocado sigue vigente. */\n    public static final Duration VIDA = Duration.ofMinutes(20);\n\n    private final Map<String, Instant> sesiones = new ConcurrentHashMap<>();\n    private final Map<String, Instant> usuarios = new ConcurrentHashMap<>();\n\n    /** Revoca una sesión (su sid) cerrada en el instante dado. */\n    public void revocarSesion(String sid, Instant ocurridoEn) {\n        if (sid == null || vencido(ocurridoEn)) {\n            return;\n        }\n        sesiones.put(sid, ocurridoEn);\n    }\n\n    /** Revoca los tokens del usuario emitidos antes del instante dado. */\n    public void revocarUsuario(String usuarioId, Instant ocurridoEn) {\n        if (usuarioId == null || vencido(ocurridoEn)) {\n            return;\n        }\n        usuarios.merge(usuarioId, ocurridoEn, (actual, nuevoValor) -> nuevoValor.isAfter(actual) ? nuevoValor : actual);\n    }\n\n    /** true si un token con ese sid, usuario y fecha de emisión ya no debe aceptarse. */\n    public boolean revocado(String sid, String usuarioId, Instant emitidoEn) {\n        limpiar();\n        if (sid != null && sesiones.containsKey(sid)) {\n            return true;\n        }\n        Instant cerradoEn = usuarioId == null ? null : usuarios.get(usuarioId);\n        return cerradoEn != null && emitidoEn != null && emitidoEn.isBefore(cerradoEn);\n    }\n\n    /** Indica si un registro de revocación ya venció y puede descartarse. */\n    private static boolean vencido(Instant ocurridoEn) {\n        return ocurridoEn == null || ocurridoEn.plus(VIDA).isBefore(Instant.now());\n    }\n\n    /** Elimina las revocaciones vencidas para no crecer sin límite. */\n    private void limpiar() {\n        Instant limite = Instant.now().minus(VIDA);\n        sesiones.values().removeIf(t -> t.isBefore(limite));\n        usuarios.values().removeIf(t -> t.isBefore(limite));\n    }\n}\n", "src/main/java/com/mx/josesaid/develop/compras/seguridad/ValidadorRevocacion.java": "package com.mx.josesaid.develop.compras.seguridad;\n\nimport org.springframework.security.oauth2.core.OAuth2Error;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidator;\nimport org.springframework.security.oauth2.core.OAuth2TokenValidatorResult;\nimport org.springframework.security.oauth2.jwt.Jwt;\n\n/** Rechaza los tokens de sesiones cerradas. Se combina con la validación estándar de firma y vencimiento. */\npublic class ValidadorRevocacion implements OAuth2TokenValidator<Jwt> {\n\n    /** Motivo que se devuelve al cliente cuando la sesión fue cerrada. */\n    public static final String MOTIVO = \"La sesion fue cerrada\";\n\n    private static final OAuth2Error REVOCADO = new OAuth2Error(\"invalid_token\", MOTIVO, null);\n\n    private final RevocacionSesiones revocaciones;\n\n    /** Recibe la copia local de revocaciones. */\n    public ValidadorRevocacion(RevocacionSesiones revocaciones) {\n        this.revocaciones = revocaciones;\n    }\n\n    /** Rechaza el JWT si su sesión o su usuario fueron revocados, aunque la firma y el vencimiento sean válidos. */\n    @Override\n    public OAuth2TokenValidatorResult validate(Jwt jwt) {\n        boolean revocado = revocaciones.revocado(jwt.getClaimAsString(\"sid\"), jwt.getSubject(), jwt.getIssuedAt());\n        return revocado ? OAuth2TokenValidatorResult.failure(REVOCADO) : OAuth2TokenValidatorResult.success();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/api/ComprasControladorAutorizacionTest.java": "package com.mx.josesaid.develop.compras.api;\n\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.compras.application.ComprasService;\nimport com.mx.josesaid.develop.compras.config.SeguridadConfig;\nimport com.mx.josesaid.develop.compras.infrastructure.idempotencia.Idempotencia;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.http.MediaType;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.GrantedAuthority;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder;\n\n/**\n * Matriz de autorización de ComprasControlador (endpoints de lectura).\n * Un rol permitido no debe recibir 401 ni 403; un rol no permitido debe recibir 403.\n */\n@WebMvcTest(ComprasControlador.class)\n@Import({SeguridadConfig.class, ComprasControladorAutorizacionTest.Configuracion.class})\nclass ComprasControladorAutorizacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n    private static final String ID = \"11111111-2222-3333-4444-555555555555\";\n    private static final String PROVEEDOR = \"{\\\"razonSocial\\\":\\\"Proveedor SA\\\",\\\"rfc\\\":\\\"AAA010101AAA\\\",\\\"correo\\\":\\\"p@ejemplo.com\\\"}\";\n    private static final String ORDEN = \"{\\\"proveedorId\\\":\\\"\" + ID + \"\\\",\\\"moneda\\\":\\\"MXN\\\",\\\"lineas\\\":[\"\n            + \"{\\\"articuloSku\\\":\\\"SKU-1\\\",\\\"cantidad\\\":2,\\\"precioUnitario\\\":10}]}\";\n    private static final String RECEPCION = \"{\\\"lineas\\\":[{\\\"articuloSku\\\":\\\"SKU-1\\\",\\\"cantidad\\\":2}]}\";\n    private static final String CANCELAR = \"{\\\"motivo\\\":\\\"Proveedor sin entrega\\\"}\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private ComprasService servicio;\n\n    @MockitoBean\n    private Idempotencia idempotencia;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    private MockHttpServletRequestBuilder lectura(String ruta, String rol) {\n        List<GrantedAuthority> autoridades = rol.isEmpty() ? List.of()\n                : List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n        return get(ruta).with(jwt().jwt(j -> j.subject(SUJETO)).authorities(autoridades));\n    }\n\n    private void permitido(String ruta, String rol) throws Exception {\n        int codigo;\n        try {\n            codigo = mvc.perform(lectura(ruta, rol)).andReturn().getResponse().getStatus();\n        } catch (jakarta.servlet.ServletException e) {\n            codigo = 200; // llegó al controlador: el rol fue aceptado\n        }\n        org.assertj.core.api.Assertions.assertThat(codigo)\n                .as(\"%s debería estar permitido para %s\", ruta, rol)\n                .isNotIn(401, 403);\n    }\n\n    private void denegado(String ruta, String rol) throws Exception {\n        mvc.perform(lectura(ruta, rol)).andExpect(status().isForbidden());\n    }\n\n    @Test\n    void buscarProveedores() throws Exception {\n        String ruta = \"/v1/proveedores?razonSocial=prueba\";\n        permitido(ruta, \"COMPRAS\");\n        permitido(ruta, \"FINANZAS\");\n        denegado(ruta, \"ALMACEN\");\n    }\n\n    @Test\n    void obtenerProveedor() throws Exception {\n        String ruta = \"/v1/proveedores/\" + ID;\n        permitido(ruta, \"COMPRAS\");\n        denegado(ruta, \"ALMACEN\");\n    }\n\n    @Test\n    void listarOrdenesCompra() throws Exception {\n        String ruta = \"/v1/ordenes-compra\";\n        permitido(ruta, \"COMPRAS\");\n        permitido(ruta, \"ALMACEN\");\n        permitido(ruta, \"DIRECCION\");\n        denegado(ruta, \"FINANZAS\");\n    }\n\n    @Test\n    void obtenerOrdenCompra() throws Exception {\n        String ruta = \"/v1/ordenes-compra/\" + ID;\n        permitido(ruta, \"COMPRAS\");\n        denegado(ruta, \"FINANZAS\");\n    }\n\n    @Test\n    void sinRolNoHayAcceso() throws Exception {\n        denegado(\"/v1/proveedores?razonSocial=prueba\", \"\");\n    }\n\n    private void escribe(MockHttpServletRequestBuilder req, String ruta, String rol, String cuerpo, boolean permite)\n            throws Exception {\n        MockHttpServletRequestBuilder conRol = req.contentType(MediaType.APPLICATION_JSON).content(cuerpo)\n                .with(jwt().jwt(j -> j.subject(SUJETO))\n                        .authorities(rol.isEmpty() ? java.util.List.of()\n                                : java.util.List.of(new SimpleGrantedAuthority(\"ROLE_\" + rol))));\n        if (permite) {\n            int codigo;\n            try {\n                codigo = mvc.perform(conRol).andReturn().getResponse().getStatus();\n            } catch (jakarta.servlet.ServletException e) {\n                codigo = 200; // llegó al controlador: el rol fue aceptado\n            }\n            org.assertj.core.api.Assertions.assertThat(codigo)\n                    .as(\"%s debería estar permitido para %s\", ruta, rol)\n                    .isNotIn(401, 403);\n        } else {\n            mvc.perform(conRol).andExpect(status().isForbidden());\n        }\n    }\n\n    @Test\n    void crearProveedor() throws Exception {\n        String ruta = \"/v1/proveedores\";\n        escribe(post(ruta), ruta, \"COMPRAS\", PROVEEDOR, true);\n        escribe(post(ruta), ruta, \"FINANZAS\", PROVEEDOR, false);\n    }\n\n    @Test\n    void crearOrdenCompra() throws Exception {\n        String ruta = \"/v1/ordenes-compra\";\n        escribe(post(ruta), ruta, \"COMPRAS\", ORDEN, true);\n        escribe(post(ruta), ruta, \"ALMACEN\", ORDEN, false);\n    }\n\n    @Test\n    void aprobarOrdenCompra() throws Exception {\n        String ruta = \"/v1/ordenes-compra/\" + ID + \"/aprobacion\";\n        escribe(post(ruta), ruta, \"COMPRAS\", \"\", true);\n        escribe(post(ruta), ruta, \"DIRECCION\", \"\", true);\n        escribe(post(ruta), ruta, \"ALMACEN\", \"\", false);\n    }\n\n    @Test\n    void registrarRecepcion() throws Exception {\n        String ruta = \"/v1/ordenes-compra/\" + ID + \"/recepciones\";\n        escribe(post(ruta), ruta, \"ALMACEN\", RECEPCION, true);\n        escribe(post(ruta), ruta, \"COMPRAS\", RECEPCION, false);\n    }\n\n    @Test\n    void cancelarOrdenCompra() throws Exception {\n        String ruta = \"/v1/ordenes-compra/\" + ID + \"/cancelacion\";\n        escribe(post(ruta), ruta, \"COMPRAS\", CANCELAR, true);\n        escribe(post(ruta), ruta, \"DIRECCION\", CANCELAR, false);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/api/ComprasControladorValidacionTest.java": "package com.mx.josesaid.develop.compras.api;\n\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.Mockito.when;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.mx.josesaid.develop.compras.application.ComprasService;\nimport com.mx.josesaid.develop.compras.infrastructure.idempotencia.Idempotencia;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.TestConfiguration;\nimport org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;\nimport org.springframework.context.annotation.Import;\nimport org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.security.oauth2.jwt.JwtDecoder;\nimport org.springframework.test.context.bean.override.mockito.MockitoBean;\nimport org.springframework.test.web.servlet.MockMvc;\n\n@WebMvcTest(ComprasControlador.class)\n@Import(ComprasControladorValidacionTest.Configuracion.class)\nclass ComprasControladorValidacionTest {\n\n    private static final String SUJETO = \"6f1c2e7a-9a3b-4c1d-8e2f-1a2b3c4d5e6f\";\n\n    @TestConfiguration\n    @EnableWebSecurity\n    static class Configuracion {\n    }\n\n    @Autowired\n    private MockMvc mvc;\n\n    @MockitoBean\n    private ComprasService servicio;\n\n    @MockitoBean\n    private Idempotencia idempotencia;\n\n    @MockitoBean\n    private JwtDecoder jwtDecoder;\n\n    @Test\n    void razonSocialDeMasDe250CaracteresDa400() throws Exception {\n        mvc.perform(get(\"/v1/proveedores\").param(\"razonSocial\", \"A\".repeat(251))\n                        .with(jwt().jwt(j -> j.subject(SUJETO))\n                                .authorities(new SimpleGrantedAuthority(\"ROLE_COMPRAS\"))))\n                .andExpect(status().isBadRequest());\n    }\n\n    @Test\n    void razonSocialDe250CaracteresEsValida() throws Exception {\n        when(servicio.buscarProveedores(any())).thenReturn(List.of());\n        mvc.perform(get(\"/v1/proveedores\").param(\"razonSocial\", \"A\".repeat(250))\n                        .with(jwt().jwt(j -> j.subject(SUJETO))\n                                .authorities(new SimpleGrantedAuthority(\"ROLE_COMPRAS\"))))\n                .andExpect(status().isOk());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/api/ComprasIT.java": "package com.mx.josesaid.develop.compras.api;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.jwt;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;\nimport static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;\nimport static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;\n\nimport com.jayway.jsonpath.JsonPath;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;\nimport org.springframework.security.core.authority.SimpleGrantedAuthority;\nimport org.springframework.test.web.servlet.MockMvc;\nimport org.springframework.test.web.servlet.MvcResult;\nimport org.springframework.test.web.servlet.request.RequestPostProcessor;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = {\n        \"compras.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\",\n        \"compras.cifrado.clave=MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=\",\n        \"compras.cifrado.indice-clave=MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=\"})\n@AutoConfigureMockMvc\n@Testcontainers\nclass ComprasIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private MockMvc mvc;\n\n    @Test\n    void flujoDeCompraConRolesRecepcionesYRfcEnmascarado() throws Exception {\n        MvcResult prov = mvc.perform(post(\"/v1/proveedores\").with(rol(\"COMPRAS\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"razonSocial\\\":\\\"Aceros del Norte SA\\\",\\\"rfc\\\":\\\"AAN010101AB3\\\",\\\"correo\\\":\\\"ventas@aceros.mx\\\"}\"))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.rfc\").value(\"AAN*******B3\"))\n                .andReturn();\n        String proveedor = JsonPath.read(prov.getResponse().getContentAsString(), \"$.id\");\n\n        // RFC duplicado: 409\n        mvc.perform(post(\"/v1/proveedores\").with(rol(\"COMPRAS\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"razonSocial\\\":\\\"Otro\\\",\\\"rfc\\\":\\\"aan010101ab3\\\",\\\"correo\\\":\\\"x@y.mx\\\"}\"))\n                .andExpect(status().isConflict());\n\n        MvcResult orden = mvc.perform(post(\"/v1/ordenes-compra\").with(usuario(\"compras-1\", \"COMPRAS\"))\n                        .contentType(\"application/json\")\n                        .content(ordenJson(proveedor)))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.estatus\").value(\"BORRADOR\"))\n                .andExpect(jsonPath(\"$.total\").value(1000))\n                .andReturn();\n        String ordenId = JsonPath.read(orden.getResponse().getContentAsString(), \"$.id\");\n\n        // El creador no aprueba su propia orden, aunque sea COMPRAS\n        mvc.perform(post(\"/v1/ordenes-compra/\" + ordenId + \"/aprobacion\").with(usuario(\"compras-1\", \"COMPRAS\")))\n                .andExpect(status().isForbidden());\n        // DIRECCION aprueba una orden que creó otro usuario\n        mvc.perform(post(\"/v1/ordenes-compra/\" + ordenId + \"/aprobacion\").with(usuario(\"direccion-1\", \"DIRECCION\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"APROBADA\"));\n\n        // Recepción mayor a lo ordenado: 409\n        mvc.perform(post(\"/v1/ordenes-compra/\" + ordenId + \"/recepciones\").with(rol(\"ALMACEN\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"lineas\\\":[{\\\"articuloSku\\\":\\\"TORN-1\\\",\\\"cantidad\\\":11}]}\"))\n                .andExpect(status().isConflict());\n\n        mvc.perform(post(\"/v1/ordenes-compra/\" + ordenId + \"/recepciones\").with(rol(\"ALMACEN\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"lineas\\\":[{\\\"articuloSku\\\":\\\"TORN-1\\\",\\\"cantidad\\\":4}]}\"))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.estatus\").value(\"RECIBIDA_PARCIAL\"));\n        mvc.perform(post(\"/v1/ordenes-compra/\" + ordenId + \"/recepciones\").with(rol(\"ALMACEN\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"lineas\\\":[{\\\"articuloSku\\\":\\\"TORN-1\\\",\\\"cantidad\\\":6}]}\"))\n                .andExpect(status().isCreated())\n                .andExpect(jsonPath(\"$.estatus\").value(\"RECIBIDA\"));\n\n        // Cancelación sin motivo: 400; orden nueva cancelada con motivo: 200\n        MvcResult otra = mvc.perform(post(\"/v1/ordenes-compra\").with(rol(\"COMPRAS\"))\n                        .contentType(\"application/json\")\n                        .content(ordenJson(proveedor)))\n                .andReturn();\n        String otraId = JsonPath.read(otra.getResponse().getContentAsString(), \"$.id\");\n        mvc.perform(post(\"/v1/ordenes-compra/\" + otraId + \"/cancelacion\").with(rol(\"COMPRAS\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"motivo\\\":\\\"\\\"}\"))\n                .andExpect(status().isBadRequest());\n        mvc.perform(post(\"/v1/ordenes-compra/\" + otraId + \"/cancelacion\").with(rol(\"COMPRAS\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"motivo\\\":\\\"Proveedor sin stock\\\"}\"))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$.estatus\").value(\"CANCELADA\"));\n    }\n\n    private static String ordenJson(String proveedor) {\n        return \"{\\\"proveedorId\\\":\\\"\" + proveedor + \"\\\",\\\"moneda\\\":\\\"MXN\\\",\\\"lineas\\\":[\"\n                + \"{\\\"articuloSku\\\":\\\"TORN-1\\\",\\\"cantidad\\\":10,\\\"precioUnitario\\\":100}]}\";\n    }\n\n    private static RequestPostProcessor rol(String rol) {\n        return jwt().authorities(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n    }\n\n    private static RequestPostProcessor usuario(String sub, String rol) {\n        return jwt().jwt(j -> j.subject(sub)).authorities(new SimpleGrantedAuthority(\"ROLE_\" + rol));\n    }\n\n    @Test\n    void buscaProveedoresPorNombreSinExponerRfcNiCorreoEnClaro() throws Exception {\n        mvc.perform(post(\"/v1/proveedores\").with(rol(\"COMPRAS\"))\n                        .contentType(org.springframework.http.MediaType.APPLICATION_JSON)\n                        .content(\"{\\\"razonSocial\\\":\\\"Busqueda Prueba SA\\\",\\\"rfc\\\":\\\"PBU010101AB1\\\",\\\"correo\\\":\\\"ventas@busqueda.mx\\\"}\"))\n                .andExpect(status().isCreated());\n\n        mvc.perform(get(\"/v1/proveedores\").param(\"razonSocial\", \"busqueda prue\").with(rol(\"FINANZAS\")))\n                .andExpect(status().isOk())\n                .andExpect(jsonPath(\"$[0].razonSocial\").value(\"Busqueda Prueba SA\"))\n                .andExpect(jsonPath(\"$[0].correo\").value(\"v***@busqueda.mx\"));\n\n        mvc.perform(get(\"/v1/proveedores\").param(\"razonSocial\", \"bu\").with(rol(\"COMPRAS\")))\n                .andExpect(status().isBadRequest());\n    }\n\n    @Test\n    void mismaIdempotencyKeyNoDuplicaLaOrden() throws Exception {\n        MvcResult prov = mvc.perform(post(\"/v1/proveedores\").with(rol(\"COMPRAS\"))\n                        .contentType(\"application/json\")\n                        .content(\"{\\\"razonSocial\\\":\\\"Replay SA\\\",\\\"rfc\\\":\\\"BBN010101AB3\\\",\\\"correo\\\":\\\"replay@aceros.mx\\\"}\"))\n                .andExpect(status().isCreated()).andReturn();\n        String proveedor = JsonPath.read(prov.getResponse().getContentAsString(), \"$.id\");\n\n        String clave = \"prueba-\" + java.util.UUID.randomUUID();\n        MvcResult primero = mvc.perform(post(\"/v1/ordenes-compra\").with(rol(\"COMPRAS\")).header(\"Idempotency-Key\", clave)\n                        .contentType(\"application/json\").content(ordenJson(proveedor)))\n                .andExpect(status().isCreated()).andReturn();\n        MvcResult reintento = mvc.perform(post(\"/v1/ordenes-compra\").with(rol(\"COMPRAS\")).header(\"Idempotency-Key\", clave)\n                        .contentType(\"application/json\").content(ordenJson(proveedor)))\n                .andExpect(status().isCreated()).andReturn();\n        assertEquals((String) JsonPath.read(primero.getResponse().getContentAsString(), \"$.id\"),\n                (String) JsonPath.read(reintento.getResponse().getContentAsString(), \"$.id\"));\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/api/ValidacionLimitesSolicitudTest.java": "package com.mx.josesaid.develop.compras.api;\n\nimport static org.assertj.core.api.Assertions.assertThat;\n\nimport java.math.BigDecimal;\nimport java.util.List;\nimport java.util.Set;\nimport java.util.UUID;\n\nimport jakarta.validation.ConstraintViolation;\nimport jakarta.validation.Validation;\nimport jakarta.validation.Validator;\n\nimport org.junit.jupiter.api.Test;\n\nimport com.mx.josesaid.develop.compras.api.ComprasControlador.CrearOrdenSolicitud;\nimport com.mx.josesaid.develop.compras.api.ComprasControlador.LineaRecepcionSolicitud;\nimport com.mx.josesaid.develop.compras.api.ComprasControlador.LineaSolicitud;\nimport com.mx.josesaid.develop.compras.api.ComprasControlador.RecepcionSolicitud;\n\nclass ValidacionLimitesSolicitudTest {\n\n    private static final Validator VALIDADOR;\n\n    static {\n        try (var fabrica = Validation.buildDefaultValidatorFactory()) {\n            VALIDADOR = fabrica.getValidator();\n        }\n    }\n\n    private static LineaSolicitud linea(String cantidad, String precio) {\n        return new LineaSolicitud(\"PAP-A4\", new BigDecimal(cantidad), new BigDecimal(precio));\n    }\n\n    private static <T> Set<ConstraintViolation<T>> errores(T objeto) {\n        return VALIDADOR.validate(objeto);\n    }\n\n    @Test\n    void aceptaUnaOrdenDentroDeLosLimites() {\n        var orden = new CrearOrdenSolicitud(UUID.randomUUID(), \"MXN\", List.of(linea(\"10\", \"85.00\")));\n\n        assertThat(errores(orden)).isEmpty();\n    }\n\n    @Test\n    void rechazaMasDeCienLineas() {\n        var lineas = java.util.Collections.nCopies(101, linea(\"1\", \"1.00\"));\n        var orden = new CrearOrdenSolicitud(UUID.randomUUID(), \"MXN\", lineas);\n\n        assertThat(errores(orden)).isNotEmpty();\n    }\n\n    @Test\n    void aceptaExactamenteCienLineas() {\n        var lineas = java.util.Collections.nCopies(100, linea(\"1\", \"1.00\"));\n        var orden = new CrearOrdenSolicitud(UUID.randomUUID(), \"MXN\", lineas);\n\n        assertThat(errores(orden)).isEmpty();\n    }\n\n    @Test\n    void rechazaCantidadConMasDeNueveEnteros() {\n        var orden = new CrearOrdenSolicitud(UUID.randomUUID(), \"MXN\",\n                List.of(linea(\"1000000000\", \"1.00\")));\n\n        assertThat(errores(orden)).isNotEmpty();\n    }\n\n    @Test\n    void rechazaCantidadConMasDeTresDecimales() {\n        var orden = new CrearOrdenSolicitud(UUID.randomUUID(), \"MXN\",\n                List.of(linea(\"1.2345\", \"1.00\")));\n\n        assertThat(errores(orden)).isNotEmpty();\n    }\n\n    @Test\n    void rechazaPrecioConMasDeDosDecimales() {\n        var orden = new CrearOrdenSolicitud(UUID.randomUUID(), \"MXN\",\n                List.of(linea(\"1\", \"85.123\")));\n\n        assertThat(errores(orden)).isNotEmpty();\n    }\n\n    @Test\n    void recepcionRechazaMasDeCienLineas() {\n        var lineas = java.util.Collections.nCopies(101,\n                new LineaRecepcionSolicitud(\"PAP-A4\", new BigDecimal(\"1\")));\n\n        assertThat(errores(new RecepcionSolicitud(lineas))).isNotEmpty();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/application/ComprasServiceListadoTest.java": "package com.mx.josesaid.develop.compras.application;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.mockito.ArgumentMatchers.any;\nimport static org.mockito.ArgumentMatchers.eq;\nimport static org.mockito.Mockito.mock;\nimport static org.mockito.Mockito.verify;\nimport static org.mockito.Mockito.when;\n\nimport com.mx.josesaid.develop.compras.domain.EstatusOrdenCompra;\nimport com.mx.josesaid.develop.compras.domain.OrdenCompraRepositorio;\nimport com.mx.josesaid.develop.compras.domain.Proveedor;\nimport com.mx.josesaid.develop.compras.domain.ProveedorRepositorio;\nimport com.mx.josesaid.develop.compras.domain.RecepcionRepositorio;\nimport com.mx.josesaid.develop.compras.domain.ResumenOrdenCompra;\nimport java.math.BigDecimal;\nimport java.time.Instant;\nimport java.util.List;\nimport java.util.Optional;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass ComprasServiceListadoTest {\n\n    private final OrdenCompraRepositorio ordenes = mock(OrdenCompraRepositorio.class);\n    private final ProveedorRepositorio proveedores = mock(ProveedorRepositorio.class);\n    private final ComprasService servicio = new ComprasService(proveedores, ordenes,\n            mock(RecepcionRepositorio.class), mock(PublicadorEventos.class),\n            new BigDecimal(\"18\"), new BigDecimal(\"1000000\"));\n\n    @Test\n    void listaConRazonSocialYLimiteFijo() {\n        UUID proveedorId = UUID.randomUUID();\n        UUID ordenId = UUID.randomUUID();\n        Instant creada = Instant.parse(\"2026-11-05T12:00:00Z\");\n        when(ordenes.listarRecientes(eq(EstatusOrdenCompra.APROBADA), eq(15)))\n                .thenReturn(List.of(new ResumenOrdenCompra(ordenId, proveedorId, EstatusOrdenCompra.APROBADA, creada)));\n        when(proveedores.buscarPorId(proveedorId))\n                .thenReturn(Optional.of(Proveedor.crear(\"Papelería del Centro\", \"PCE010101AB1\", \"ventas@pce.mx\")));\n\n        List<ComprasService.ResumenListado> lista = servicio.listarOrdenesRecientes(EstatusOrdenCompra.APROBADA);\n\n        assertThat(lista).hasSize(1);\n        assertThat(lista.get(0).id()).isEqualTo(ordenId);\n        assertThat(lista.get(0).razonSocialProveedor()).isEqualTo(\"Papelería del Centro\");\n        assertThat(lista.get(0).creadaUtc()).isEqualTo(creada);\n        verify(ordenes).listarRecientes(EstatusOrdenCompra.APROBADA, ComprasService.LIMITE_LISTADO_ORDENES);\n    }\n\n    @Test\n    void proveedorInexistenteDejaRazonSocialVacia() {\n        UUID proveedorId = UUID.randomUUID();\n        when(ordenes.listarRecientes(any(), eq(15)))\n                .thenReturn(List.of(new ResumenOrdenCompra(UUID.randomUUID(), proveedorId,\n                        EstatusOrdenCompra.BORRADOR, Instant.now())));\n        when(proveedores.buscarPorId(proveedorId)).thenReturn(Optional.empty());\n\n        List<ComprasService.ResumenListado> lista = servicio.listarOrdenesRecientes(null);\n\n        assertThat(lista.get(0).razonSocialProveedor()).isEmpty();\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/config/RelojConfigTest.java": "package com.mx.josesaid.develop.compras.config;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport java.time.ZoneId;\nimport org.junit.jupiter.api.Test;\n\nclass RelojConfigTest {\n\n    @Test\n    void relojUsaLaZonaDeOperacion() {\n        assertEquals(ZoneId.of(\"America/Mexico_City\"), new RelojConfig().reloj().getZone());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/domain/OrdenCompraAprobacionTest.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport java.util.List;\nimport java.util.UUID;\n\nimport org.junit.jupiter.api.Test;\n\nclass OrdenCompraAprobacionTest {\n\n    private static final BigDecimal TIPO_CAMBIO = new BigDecimal(\"18\");\n    private static final BigDecimal LIMITE = new BigDecimal(\"1000000\");\n\n    private static Proveedor activo() {\n        return Proveedor.crear(\"Aceros del Norte SA\", \"AAN010101AB3\", \"ventas@aceros.mx\");\n    }\n\n    /** Orden de un solo renglón con el total indicado. */\n    private static OrdenCompra orden(String moneda, String total, String creadaPor) {\n        List<LineaOrden> lineas = List.of(LineaOrden.nueva(\"TORN-1\", BigDecimal.ONE, new BigDecimal(total)));\n        return OrdenCompra.crear(activo(), moneda, lineas, creadaPor);\n    }\n\n    @Test\n    void comprasApruebaUnaOrdenMenorAlLimiteQueNoCreo() {\n        OrdenCompra o = orden(\"MXN\", \"1000\", \"u-compras-1\");\n\n        o.aprobar(\"u-compras-2\", false, TIPO_CAMBIO, LIMITE);\n\n        assertThat(o.getEstatus()).isEqualTo(EstatusOrdenCompra.APROBADA);\n    }\n\n    @Test\n    void nadieApruebaUnaOrdenQueCreo() {\n        OrdenCompra o = orden(\"MXN\", \"1000\", \"u-compras-1\");\n\n        assertThatThrownBy(() -> o.aprobar(\"u-compras-1\", false, TIPO_CAMBIO, LIMITE))\n                .isInstanceOf(AprobacionNoPermitidaException.class)\n                .hasMessageContaining(\"tú creaste\");\n        assertThatThrownBy(() -> o.aprobar(\"u-compras-1\", true, TIPO_CAMBIO, LIMITE))\n                .isInstanceOf(AprobacionNoPermitidaException.class);\n        assertThat(o.getEstatus()).isEqualTo(EstatusOrdenCompra.BORRADOR);\n    }\n\n    @Test\n    void direccionApruebaUnaOrdenQueOtroCreo() {\n        OrdenCompra o = orden(\"MXN\", \"1000\", \"u-compras-1\");\n\n        o.aprobar(\"u-direccion\", true, TIPO_CAMBIO, LIMITE);\n\n        assertThat(o.getEstatus()).isEqualTo(EstatusOrdenCompra.APROBADA);\n    }\n\n    @Test\n    void comprasNoApruebaUnaOrdenDeUnMillonDeDolaresOMas() {\n        OrdenCompra o = orden(\"USD\", \"1000000\", \"u-compras-1\");\n\n        assertThatThrownBy(() -> o.aprobar(\"u-compras-2\", false, TIPO_CAMBIO, LIMITE))\n                .isInstanceOf(AprobacionNoPermitidaException.class)\n                .hasMessageContaining(\"1,000,000 USD\");\n    }\n\n    @Test\n    void unaOrdenEnPesosSeConvierteAUsdParaComparar() {\n        // 18,000,000 MXN a 18 MXN por USD son exactamente 1,000,000 USD: el límite es inclusivo.\n        OrdenCompra enLimite = orden(\"MXN\", \"18000000\", \"u-compras-1\");\n        assertThatThrownBy(() -> enLimite.aprobar(\"u-compras-2\", false, TIPO_CAMBIO, LIMITE))\n                .isInstanceOf(AprobacionNoPermitidaException.class);\n\n        // 17,999,999 MXN son menos de 1,000,000 USD: COMPRAS sí aprueba.\n        OrdenCompra debajo = orden(\"MXN\", \"17999999\", \"u-compras-1\");\n        debajo.aprobar(\"u-compras-2\", false, TIPO_CAMBIO, LIMITE);\n        assertThat(debajo.getEstatus()).isEqualTo(EstatusOrdenCompra.APROBADA);\n    }\n\n    @Test\n    void direccionApruebaUnaOrdenDeUnMillonDeDolaresOMas() {\n        OrdenCompra o = orden(\"USD\", \"2000000\", \"u-compras-1\");\n\n        o.aprobar(\"u-direccion\", true, TIPO_CAMBIO, LIMITE);\n\n        assertThat(o.getEstatus()).isEqualTo(EstatusOrdenCompra.APROBADA);\n    }\n\n    @Test\n    void unaOrdenAntiguaSinCreadorSoloLaApruebaDireccionAunqueSeaChica() {\n        OrdenCompra antigua = OrdenCompra.reconstruir(UUID.randomUUID(), UUID.randomUUID(), \"MXN\",\n                EstatusOrdenCompra.BORRADOR, null,\n                List.of(LineaOrden.nueva(\"TORN-1\", BigDecimal.ONE, new BigDecimal(\"100\"))), null);\n\n        assertThatThrownBy(() -> antigua.aprobar(\"u-compras-2\", false, TIPO_CAMBIO, LIMITE))\n                .isInstanceOf(AprobacionNoPermitidaException.class)\n                .hasMessageContaining(\"antes de registrar su creador\");\n\n        antigua.aprobar(\"u-direccion\", true, TIPO_CAMBIO, LIMITE);\n        assertThat(antigua.getEstatus()).isEqualTo(EstatusOrdenCompra.APROBADA);\n    }\n\n    @Test\n    void laOrdenNecesitaUnCreador() {\n        assertThatThrownBy(() -> orden(\"MXN\", \"1000\", \" \"))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n\n    @Test\n    void limiteConfigurableCambiaElUmbral() {\n        // 500,000 USD: con límite de 400,000 requiere DIRECCION; con el límite por defecto COMPRAS la aprueba.\n        OrdenCompra o = orden(\"USD\", \"500000\", \"u-compras-1\");\n        assertThatThrownBy(() -> o.aprobar(\"u-compras-2\", false, TIPO_CAMBIO, new BigDecimal(\"400000\")))\n                .isInstanceOf(AprobacionNoPermitidaException.class)\n                .hasMessageContaining(\"400,000 USD\");\n        o.aprobar(\"u-compras-2\", false, TIPO_CAMBIO, LIMITE);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/domain/OrdenCompraTest.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport java.util.List;\nimport org.junit.jupiter.api.Test;\n\nclass OrdenCompraTest {\n\n    private static final BigDecimal TIPO_CAMBIO = new BigDecimal(\"18\");\n    private static final BigDecimal LIMITE = new BigDecimal(\"1000000\");\n\n    private static Proveedor activo() {\n        return Proveedor.crear(\"Aceros del Norte SA\", \"AAN010101AB3\", \"ventas@aceros.mx\");\n    }\n\n    private static List<LineaOrden> lineas() {\n        return List.of(LineaOrden.nueva(\"TORN-1\", new BigDecimal(\"10\"), new BigDecimal(\"100\")));\n    }\n\n    @Test\n    void calculaTotalDeLasLineas() {\n        OrdenCompra o = OrdenCompra.crear(activo(), \"MXN\", lineas(), \"u-compras\");\n        assertThat(o.total()).isEqualByComparingTo(\"1000.00\");\n        assertThat(o.getEstatus()).isEqualTo(EstatusOrdenCompra.BORRADOR);\n    }\n\n    @Test\n    void proveedorInactivoNoRecibeOrdenes() {\n        Proveedor bloqueado = Proveedor.reconstruir(java.util.UUID.randomUUID(), \"X\", \"AAN010101AB3\",\n                \"a@b.mx\", EstatusProveedor.BLOQUEADO);\n        assertThatThrownBy(() -> OrdenCompra.crear(bloqueado, \"MXN\", lineas(), \"u-compras\"))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n\n    @Test\n    void recepcionNoPuedeExcederLoOrdenado() {\n        OrdenCompra o = OrdenCompra.crear(activo(), \"MXN\", lineas(), \"u-compras\");\n        o.aprobar(\"u-direccion\", true, TIPO_CAMBIO, LIMITE);\n        o.recibir(\"TORN-1\", new BigDecimal(\"6\"));\n        assertThat(o.getEstatus()).isEqualTo(EstatusOrdenCompra.RECIBIDA_PARCIAL);\n        assertThatThrownBy(() -> o.recibir(\"TORN-1\", new BigDecimal(\"5\")))\n                .isInstanceOf(ConflictoException.class);\n        o.recibir(\"TORN-1\", new BigDecimal(\"4\"));\n        assertThat(o.getEstatus()).isEqualTo(EstatusOrdenCompra.RECIBIDA);\n    }\n\n    @Test\n    void aprobadaSoloSeCancelaConMotivo() {\n        OrdenCompra o = OrdenCompra.crear(activo(), \"MXN\", lineas(), \"u-compras\");\n        o.aprobar(\"u-direccion\", true, TIPO_CAMBIO, LIMITE);\n        assertThatThrownBy(() -> o.cancelar(\" \")).isInstanceOf(SolicitudInvalidaException.class);\n        assertThatThrownBy(() -> o.aprobar(\"u-direccion\", true, TIPO_CAMBIO, LIMITE)).isInstanceOf(ConflictoException.class);\n        o.cancelar(\"Proveedor sin stock\");\n        assertThat(o.getEstatus()).isEqualTo(EstatusOrdenCompra.CANCELADA);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/domain/ProveedorTest.java": "package com.mx.josesaid.develop.compras.domain;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport org.junit.jupiter.api.Test;\n\nclass ProveedorTest {\n\n    @Test\n    void normalizaRfcYCorreo() {\n        Proveedor p = Proveedor.crear(\"Aceros del Norte SA\", \" aan010101ab3 \", \"Ventas@Aceros.MX\");\n        assertThat(p.getRfc()).isEqualTo(\"AAN010101AB3\");\n        assertThat(p.getCorreo()).isEqualTo(\"ventas@aceros.mx\");\n        assertThat(p.estaActivo()).isTrue();\n    }\n\n    @Test\n    void rfcInvalidoSeRechaza() {\n        assertThatThrownBy(() -> Proveedor.crear(\"X\", \"ABC\", \"a@b.mx\"))\n                .isInstanceOf(ReglaDeNegocioException.class)\n                .hasMessageContaining(\"RFC\");\n    }\n\n    @Test\n    void correoInvalidoSeRechaza() {\n        assertThatThrownBy(() -> Proveedor.crear(\"X\", \"AAN010101AB3\", \"sin-arroba\"))\n                .isInstanceOf(ReglaDeNegocioException.class);\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/infrastructure/ProtectorDatosTest.java": "package com.mx.josesaid.develop.compras.infrastructure;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport com.mx.josesaid.develop.compras.infrastructure.seguridad.ProtectorDatos;\nimport java.nio.ByteBuffer;\nimport java.nio.charset.StandardCharsets;\nimport java.security.SecureRandom;\nimport java.util.Base64;\nimport javax.crypto.Cipher;\nimport javax.crypto.spec.GCMParameterSpec;\nimport javax.crypto.spec.SecretKeySpec;\nimport org.junit.jupiter.api.Test;\n\nclass ProtectorDatosTest {\n\n    private static final String CLAVE = \"MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=\";\n    private static final String CLAVE_2 = \"YWJjZGVmMDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODk=\";\n\n    private final ProtectorDatos protector = new ProtectorDatos(CLAVE, CLAVE);\n\n    @Test\n    void cifradoIdaYVueltaYNoRevelaElClaro() {\n        String cifrado = protector.cifrar(\"AAN010101AB3\");\n        assertThat(cifrado).doesNotContain(\"AAN010101AB3\");\n        assertThat(protector.descifrar(cifrado)).isEqualTo(\"AAN010101AB3\");\n    }\n\n    @Test\n    void cadaCifradoEsDistintoPorqueUsaIvAleatorio() {\n        assertThat(protector.cifrar(\"mismo\")).isNotEqualTo(protector.cifrar(\"mismo\"));\n    }\n\n    @Test\n    void indiceEsDeterministaParaBuscarPorIgualdad() {\n        assertThat(protector.indice(\"AAN010101AB3\")).isEqualTo(protector.indice(\"AAN010101AB3\"));\n        assertThat(protector.indice(\"AAN010101AB3\")).isNotEqualTo(protector.indice(\"AAN010101AB4\"));\n    }\n\n    @Test\n    void cifraConPrefijoDeVersionActiva() {\n        assertThat(protector.cifrar(\"AAN010101AB3\")).startsWith(\"v1:\");\n    }\n\n    @Test\n    void leeValorAntiguoSinPrefijoComoVersionUno() {\n        String antiguo = cifrarSinPrefijo(\"AAN010101AB3\", CLAVE);\n        assertThat(protector.descifrar(antiguo)).isEqualTo(\"AAN010101AB3\");\n    }\n\n    @Test\n    void rotaCifrandoConVersionNuevaYLeeLaAnterior() {\n        ProtectorDatos rotado = new ProtectorDatos(\"\", \"1:\" + CLAVE + \",2:\" + CLAVE_2, 2, CLAVE);\n\n        String nuevo = rotado.cifrar(\"nuevo\");\n        String viejo = protector.cifrar(\"viejo\");\n\n        assertThat(nuevo).startsWith(\"v2:\");\n        assertThat(rotado.descifrar(nuevo)).isEqualTo(\"nuevo\");\n        assertThat(rotado.descifrar(viejo)).isEqualTo(\"viejo\");\n    }\n\n    @Test\n    void versionNoConfiguradaFalla() {\n        assertThatThrownBy(() -> protector.descifrar(\"v9:\" + Base64.getEncoder().encodeToString(new byte[40])))\n                .isInstanceOf(IllegalStateException.class)\n                .hasMessageContaining(\"Versión de clave de cifrado no configurada: 9\");\n    }\n\n    @Test\n    void versionActivaDebeEstarConfigurada() {\n        assertThatThrownBy(() -> new ProtectorDatos(\"\", \"1:\" + CLAVE, 2, CLAVE))\n                .isInstanceOf(IllegalStateException.class);\n    }\n\n    /** Replica el formato anterior (sin prefijo) para verificar la compatibilidad. */\n    private static String cifrarSinPrefijo(String texto, String claveBase64) {\n        try {\n            byte[] iv = new byte[12];\n            new SecureRandom().nextBytes(iv);\n            Cipher cipher = Cipher.getInstance(\"AES/GCM/NoPadding\");\n            cipher.init(Cipher.ENCRYPT_MODE,\n                    new SecretKeySpec(Base64.getDecoder().decode(claveBase64), \"AES\"), new GCMParameterSpec(128, iv));\n            byte[] cifrado = cipher.doFinal(texto.getBytes(StandardCharsets.UTF_8));\n            return Base64.getEncoder().encodeToString(ByteBuffer.allocate(iv.length + cifrado.length).put(iv).put(cifrado).array());\n        } catch (Exception e) {\n            throw new IllegalStateException(e);\n        }\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/infrastructure/idempotencia/RegistroIdempotenciaIT.java": "package com.mx.josesaid.develop.compras.infrastructure.idempotencia;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\nimport static org.junit.jupiter.api.Assertions.assertFalse;\nimport static org.junit.jupiter.api.Assertions.assertTrue;\n\nimport java.time.Clock;\nimport java.time.Instant;\nimport java.time.ZoneOffset;\nimport org.flywaydb.core.Flyway;\nimport org.junit.jupiter.api.BeforeEach;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.springframework.jdbc.datasource.DriverManagerDataSource;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Reserva de Idempotency-Key contra PostgreSQL real (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@Testcontainers\nclass RegistroIdempotenciaIT {\n\n    @Container\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    private static final Instant T0 = Instant.parse(\"2026-11-05T12:00:00Z\");\n\n    private JdbcTemplate jdbc;\n\n    @BeforeEach\n    void migrarBaseLimpia() {\n        DriverManagerDataSource ds = new DriverManagerDataSource(\n                postgres.getJdbcUrl(), postgres.getUsername(), postgres.getPassword());\n        Flyway flyway = Flyway.configure().dataSource(ds).cleanDisabled(false).load();\n        flyway.clean();\n        flyway.migrate();\n        jdbc = new JdbcTemplate(ds);\n    }\n\n    private RegistroIdempotencia registroEn(Instant instante) {\n        return new RegistroIdempotencia(jdbc, Clock.fixed(instante, ZoneOffset.UTC));\n    }\n\n    @Test\n    void reservaFrescaNoSeRetoma() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertFalse(registroEn(T0.plusSeconds(60)).reservar(\"k1\", \"h1\"));\n    }\n\n    @Test\n    void reservaSinCompletarSeRetomaTrasLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h2\"));\n        assertEquals(\"h2\", registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().huella());\n        assertFalse(registroEn(T0.plusSeconds(200)).reservar(\"k1\", \"h2\"));\n    }\n\n    @Test\n    void respuestaCompletadaNoSeRetomaAunquePaseLaConcesion() {\n        assertTrue(registroEn(T0).reservar(\"k1\", \"h1\"));\n        registroEn(T0).completar(\"k1\", 201, \"{}\");\n        assertFalse(registroEn(T0.plusSeconds(180)).reservar(\"k1\", \"h1\"));\n        assertTrue(registroEn(T0.plusSeconds(180)).buscar(\"k1\").orElseThrow().completada());\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/infrastructure/indicadores/PublicadorIndicadoresOrdenesIT.java": "package com.mx.josesaid.develop.compras.infrastructure.indicadores;\n\nimport static org.junit.jupiter.api.Assertions.assertEquals;\n\nimport com.jayway.jsonpath.JsonPath;\nimport java.time.Duration;\nimport java.time.YearMonth;\nimport java.time.ZoneId;\nimport java.util.Collections;\nimport java.util.Properties;\nimport java.util.UUID;\nimport org.apache.kafka.clients.consumer.ConsumerConfig;\nimport org.apache.kafka.clients.consumer.KafkaConsumer;\nimport org.apache.kafka.common.serialization.StringDeserializer;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.test.context.SpringBootTest;\nimport org.springframework.boot.testcontainers.service.connection.ServiceConnection;\nimport org.springframework.jdbc.core.JdbcTemplate;\nimport org.testcontainers.junit.jupiter.Container;\nimport org.testcontainers.junit.jupiter.Testcontainers;\nimport org.testcontainers.kafka.KafkaContainer;\nimport org.testcontainers.postgresql.PostgreSQLContainer;\n\n/** Integración con PostgreSQL y Kafka reales (Testcontainers). Requiere Docker; corre con 'mvn verify'. */\n@SpringBootTest(properties = {\n        \"compras.jwt.jwks-uri=http://localhost:9/.well-known/jwks.json\",\n        \"compras.cifrado.clave=MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=\",\n        \"compras.cifrado.indice-clave=MDEyMzQ1Njc4OWFiY2RlZjAxMjM0NTY3ODlhYmNkZWY=\"})\n@Testcontainers\nclass PublicadorIndicadoresOrdenesIT {\n\n    @Container\n    @ServiceConnection\n    static PostgreSQLContainer postgres = new PostgreSQLContainer(\"postgres:17-alpine\");\n\n    @Container\n    @ServiceConnection\n    static KafkaContainer kafka = new KafkaContainer(\"apache/kafka:4.0.0\");\n\n    @Autowired\n    private JdbcTemplate jdbc;\n\n    @Autowired\n    private PublicadorIndicadoresOrdenes publicador;\n\n    private static final ZoneId ZONA = ZoneId.of(\"America/Mexico_City\");\n\n    @Test\n    void ordenesDelMesCuentanTodasLasCreadasConFecha() {\n        String periodo = YearMonth.now(ZONA).toString();\n        UUID proveedor = proveedor();\n        orden(proveedor, \"BORRADOR\");\n        orden(proveedor, \"APROBADA\");\n        orden(proveedor, \"CANCELADA\");\n        ordenSinFecha(proveedor, \"APROBADA\");  // excluida: sin fecha; V4 solo asigna fecha a las órdenes existentes al migrar\n\n        publicador.publicarPeriodo(periodo);\n\n        String payload = leerIndicador(PublicadorIndicadoresOrdenes.AREA + \"|\" + PublicadorIndicadoresOrdenes.NOMBRE + \"|\" + periodo);\n        assertEquals(\"COMPRAS_PROVEEDORES\", JsonPath.read(payload, \"$.area\"));\n        assertEquals(3.0, ((Number) JsonPath.read(payload, \"$.valor\")).doubleValue(), 0.001);\n\n        String canceladas = leerIndicador(PublicadorIndicadoresOrdenes.AREA + \"|\" + PublicadorIndicadoresOrdenes.NOMBRE_CANCELADAS + \"|\" + periodo);\n        assertEquals(1.0, ((Number) JsonPath.read(canceladas, \"$.valor\")).doubleValue(), 0.001);\n    }\n\n    private UUID proveedor() {\n        UUID id = UUID.randomUUID();\n        jdbc.update(\"\"\"\n                INSERT INTO proveedores (id, razon_social, rfc_cifrado, rfc_indice, correo_cifrado, estatus, version)\n                VALUES (?, 'Proveedor SA', 'cifrado', ?, 'cifrado', 'ACTIVO', 0)\n                \"\"\", id, UUID.randomUUID().toString());\n        return id;\n    }\n\n    /** Usa el DEFAULT now() de la columna, como ocurre en el servicio. */\n    private void orden(UUID proveedor, String estatus) {\n        jdbc.update(\"\"\"\n                INSERT INTO ordenes_compra (id, proveedor_id, moneda, estatus, version)\n                VALUES (?, ?, 'MXN', ?, 0)\n                \"\"\", UUID.randomUUID(), proveedor, estatus);\n    }\n\n    private void ordenSinFecha(UUID proveedor, String estatus) {\n        jdbc.update(\"\"\"\n                INSERT INTO ordenes_compra (id, proveedor_id, moneda, estatus, version, creado_utc)\n                VALUES (?, ?, 'MXN', ?, 0, NULL)\n                \"\"\", UUID.randomUUID(), proveedor, estatus);\n    }\n\n    private String leerIndicador(String clave) {\n        try (KafkaConsumer<String, String> consumidor = new KafkaConsumer<>(propiedades())) {\n            consumidor.subscribe(Collections.singletonList(\"indicadores-areas\"));\n            long limite = System.currentTimeMillis() + 30_000;\n            while (System.currentTimeMillis() < limite) {\n                for (var registro : consumidor.poll(Duration.ofMillis(500))) {\n                    if (clave.equals(registro.key())) {\n                        return registro.value();\n                    }\n                }\n            }\n            throw new AssertionError(\"No llegó el indicador \" + clave);\n        }\n    }\n\n    private Properties propiedades() {\n        Properties p = new Properties();\n        p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG, kafka.getBootstrapServers());\n        p.put(ConsumerConfig.GROUP_ID_CONFIG, \"test-\" + UUID.randomUUID());\n        p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG, \"earliest\");\n        p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG, StringDeserializer.class);\n        return p;\n    }\n}\n", "src/test/java/com/mx/josesaid/develop/compras/infrastructure/seguridad/RecifradorPorLotesTest.java": "package com.mx.josesaid.develop.compras.infrastructure.seguridad;\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.security.SecureRandom;\nimport java.util.ArrayList;\nimport java.util.Base64;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.UUID;\nimport org.junit.jupiter.api.Test;\n\nclass RecifradorPorLotesTest {\n\n    private static final String IDX = Base64.getEncoder().encodeToString(new byte[32]);\n    private final SecureRandom aleatorio = new SecureRandom();\n\n    private String clave() {\n        byte[] b = new byte[32];\n        aleatorio.nextBytes(b);\n        return Base64.getEncoder().encodeToString(b);\n    }\n\n    private ProtectorDatos protector(String k1, String k2, int activa) {\n        return new ProtectorDatos(\"\", \"1:\" + k1 + \",2:\" + k2, activa, IDX);\n    }\n\n    @Test\n    void recifraLosRfcPendientesYLosDejaDescifrablesConLaVersionNueva() {\n        String k1 = clave();\n        String k2 = clave();\n        ProtectorDatos vieja = protector(k1, k2, 1);\n        ProtectorDatos nueva = protector(k1, k2, 2);\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria(nueva);\n        almacen.agregar(UUID.randomUUID(), vieja.cifrar(\"AAN010101AB3\"));\n        almacen.agregar(UUID.randomUUID(), vieja.cifrar(\"PEGJ800101AAA\"));\n\n        int recifradas = new RecifradorPorLotes(almacen, 10, v -> nueva.cifrar(nueva.descifrar(v)))\n                .ejecutar(\"proveedores\", \"rfc_cifrado\");\n\n        assertThat(recifradas).isEqualTo(2);\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(v).startsWith(\"v2:\"));\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(nueva.descifrar(v))\n                .isIn(\"AAN010101AB3\", \"PEGJ800101AAA\"));\n    }\n\n    @Test\n    void respetaElTamanoDeLote() {\n        String k1 = clave();\n        String k2 = clave();\n        ProtectorDatos vieja = protector(k1, k2, 1);\n        ProtectorDatos nueva = protector(k1, k2, 2);\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria(nueva);\n        for (int i = 0; i < 5; i++) {\n            almacen.agregar(UUID.randomUUID(), vieja.cifrar(\"dato\" + i));\n        }\n\n        new RecifradorPorLotes(almacen, 2, v -> nueva.cifrar(nueva.descifrar(v))).ejecutar(\"proveedores\", \"correo_cifrado\");\n\n        assertThat(almacen.limitesPedidos).containsOnly(2);\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(v).startsWith(\"v2:\"));\n    }\n\n    @Test\n    void reanudarDespuesDeUnCorteNoDuplicaNiPierde() {\n        String k1 = clave();\n        String k2 = clave();\n        ProtectorDatos vieja = protector(k1, k2, 1);\n        ProtectorDatos nueva = protector(k1, k2, 2);\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria(nueva);\n        almacen.agregar(UUID.randomUUID(), vieja.cifrar(\"uno\"));\n        almacen.agregar(UUID.randomUUID(), vieja.cifrar(\"dos\"));\n        almacen.fallarEnActualizacion = 2;\n        RecifradorPorLotes recifrador = new RecifradorPorLotes(almacen, 1, v -> nueva.cifrar(nueva.descifrar(v)));\n\n        assertThatThrownBy(() -> recifrador.ejecutar(\"proveedores\", \"rfc_cifrado\"))\n                .isInstanceOf(IllegalStateException.class);\n        almacen.fallarEnActualizacion = 0;\n        int segunda = recifrador.ejecutar(\"proveedores\", \"rfc_cifrado\");\n\n        assertThat(segunda).isEqualTo(1);\n        assertThat(almacen.valores()).allSatisfy(v -> assertThat(v).startsWith(\"v2:\"));\n    }\n\n    @Test\n    void siUnaFilaCambiaDuranteElProcesoSeAvisa() {\n        String k1 = clave();\n        String k2 = clave();\n        ProtectorDatos vieja = protector(k1, k2, 1);\n        ProtectorDatos nueva = protector(k1, k2, 2);\n        AlmacenEnMemoria almacen = new AlmacenEnMemoria(nueva);\n        almacen.agregar(UUID.randomUUID(), vieja.cifrar(\"x\"));\n        almacen.rechazarActualizacion = true;\n\n        assertThatThrownBy(() -> new RecifradorPorLotes(almacen, 10, v -> nueva.cifrar(nueva.descifrar(v)))\n                .ejecutar(\"proveedores\", \"rfc_cifrado\"))\n                .isInstanceOf(IllegalStateException.class)\n                .hasMessageContaining(\"cambió durante el proceso\");\n    }\n\n    /** Almacén en memoria con las mismas reglas que la consulta JDBC. */\n    private static final class AlmacenEnMemoria implements RecifradorPorLotes.Almacen {\n        private final ProtectorDatos protector;\n        private final Map<Object, String> filas = new LinkedHashMap<>();\n        private final List<Integer> limitesPedidos = new ArrayList<>();\n        private int fallarEnActualizacion;\n        private int actualizaciones;\n        private boolean rechazarActualizacion;\n\n        AlmacenEnMemoria(ProtectorDatos protector) {\n            this.protector = protector;\n        }\n\n        void agregar(Object id, String valor) {\n            filas.put(id, valor);\n        }\n\n        List<String> valores() {\n            return new ArrayList<>(filas.values());\n        }\n\n        @Override\n        public List<RecifradorPorLotes.Fila> pendientes(String tabla, String columna, int limite) {\n            limitesPedidos.add(limite);\n            String prefijo = \"v\" + protector.versionActiva() + \":\";\n            List<RecifradorPorLotes.Fila> salida = new ArrayList<>();\n            for (Map.Entry<Object, String> e : filas.entrySet()) {\n                if (!e.getValue().startsWith(prefijo) && salida.size() < limite) {\n                    salida.add(new RecifradorPorLotes.Fila(e.getKey(), e.getValue()));\n                }\n            }\n            return salida;\n        }\n\n        @Override\n        public boolean actualizar(String tabla, String columna, Object id, String valorAnterior, String valorNuevo) {\n            if (fallarEnActualizacion > 0 && ++actualizaciones == fallarEnActualizacion) {\n                throw new IllegalStateException(\"corte simulado\");\n            }\n            if (rechazarActualizacion || !valorAnterior.equals(filas.get(id))) {\n                return false;\n            }\n            filas.put(id, valorNuevo);\n            return true;\n        }\n    }\n}\n"};
